(window.GIM_TS=window.GIM_TS||{})["Tamid.2"]={"from":48,"a":[["\u0003במסיבה\u0004 (בדרך סיבובית) \u0003ההולכת לו תחת הבירה\u0004 (המקדש), ולא בעזרה עצמה (שהרי בעל קרי הוא, ואסור להיות בעזרה). \u0003ו\u0004על מנת להאיר את הדרך התת קרקעית הזו, היו \u0003נרות דולקין מכאן ומכאן,\u0004 משני צדיה. \u0003עד שהוא מגיע לבית הטבילה. ומדורה היתה\u0004 דולקת \u0003שם,\u0004 כדי לחמם את הכהנים לאחר שטבלו. \u0003ו\u0004כן היה שם \u0003בית הכסא של כבוד,\u0004 כדי שיטיל בו מימיו קודם שיטבול. ו\u0003זה היה כבודו:\u0004 שהמבקש להיכנס אליו להפנות לצרכיו ו\u0003מצאו\u0004 שהוא \u0003נעול\u0004 — מתוך כך הריהו \u0003יודע שיש שם אדם,\u0004 והריהו ממתין לו עד שיצא, ויכנס לאחריו. ואם מצאו כשהוא \u0003פתוח\u0004 — \u0003בידוע שאין שם אדם,\u0004 והריהו נכנס לשם.","ולאחר מכן, \u0003ירד\u0004 למקוה הטהרה, \u0003וטבל, עלה\u0004 מהמקוה \u0003ונסתפג\u0004 (ניגב עצמו במגבת), \u0003ונתחמם כנגד\u0004 אש \u0003המדורה.\u0004 ומשעשה כן, הוא חוזר ו\u0003בא\u0004 לבית המוקד, \u0003ו\u0004שם הוא \u0003ישב לו אצל אחיו הכהנים, עד\u0004 השחר \u0003ש\u0004אז \u0003היו\u0004 ה\u0003שערים\u0004 (דלתות העזרה) \u0003נפתחים,\u0004 ואזי הוא \u0003יוצא\u0004 אל מחוץ למקדש \u0003והולך לו,\u0004 שהרי אף לאחר שטבל הריהו טבול יום, ואינו טהור לגמרי עד שתערב שמשו ואסור הוא בשהייה במקדש.","כל \u0003מי\u0004 מן הכהנים שבאותו בית אב העובד באותו יום בבית המקדש \u0003שהוא רוצה לתרום את המזבח\u0004 (תרומת הדשן, סילוק האפר מעל המזבח החיצון), הריהו \u0003משכים\u0004 (מקדים) \u0003וטובל\u0004 כנדרש מכל הנכנסים לעזרה \u0003עד שלא\u0004 (בטרם) \u0003יבא הממונה\u0004 על ההגרלה (ה\"פיס\") הנערכת בין הכהנים מי מהם יעשה כל אחת מעבודות המקדש, והגרלה זו על תרומת הדשן היא הראשונה, שכן היא העבודה הראשונה הנעשית בכל יום. ושואל: וכי באיזה שעה בא הממונה, וחוזר ומשיב: \u0003לא כל העתים\u0004 בהן בא הממונה \u0003שוות,\u0004 ש\u0003פעמים שהוא בא מקרות הגבר\u0004 (קריאת התרנגול), \u0003או\u0004 בזמן ה\u0003סמוך לו\u0004 אם \u0003מלפניו או מאחריו.\u0004","וכש\u0003הממונה בא\u0004 אל בית המוקד בו היו כהני אותו בית אב, \u0003ודפק\u0004 (מקיש בשער) \u0003עליהן\u0004 (אליהם), שיפתחו לו את השער, \u0003ו\u0004כש\u0003הן פתחו לו, אמר להן: מי שטבל\u0004 — \u0003יבא ויפיס\u0004 (ישתתף בהגרלה), ולאחר מכן עמדו אלה שטבלו ו\u0003הפיסו\u0004 (הגרילו), ו\u0003מי שזכה\u0004 לעבוד את עבודת תרומת הדשן — \u0003זכה בו.\u0004","שנינו במשנתנו כי הכהנים שומרים בשלושה מקומות בבית המקדש. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו,\u0006 מה המקור בתורה לחובת השמירה\u0005]?\u0006 \u0003אמר אביי\u0004 בתשובה: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והחונים לפני המשכן קדמה לפני אהל מועד מזרחה משה ואהרן ובניו שומרים משמרת המקדש למשמרת בני ישראל\"\u0004 (במדבר ג, לח).","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית הדברים: \u0003אין\u0004 \u0005[\u0006אכן \u0005כן],\u0006 מתוך מקרא זה, \u0003שימור בעלמא\u0004 \u0005[סתם],\u0006 \u0003אשכחן דבעי\u0004 \u0005[מצאנו,\u0006 למדנו \u0005שצריך],\u0006 וכן למדנו ממנו כי \u0003כהנים ולוים\u0004 הם המצווים על \u0003שימור\u0004 זה (שהרי נאמר בכתוב \"משה ואהרן\" — משה הלוי, ואהרן הכהן), \u0003מיהו מתניתין קתני\u0004 \u0005[ואולם\u0006 ב\u0005משנתנו שנינו]\u0006 כי הכהנים והלויים לא היו שומרים באותם מקומות, אלא \u0003בשלשה מקומות הכהנים שומרים בבית המקדש, ו\u0004אילו \u0003הלוים\u0004 שומרים \u0003בעשרים ואחד מקום\u0004 אחרים, וכפי ששנינו במשנה בתחילת מסכת מידות, \u0003ואילו\u0004 ב\u0003קרא\u0004 \u0005[\u0006ב\u0005כתוב]\u0006 זה, שמירתם של ה\u0003כהנים ו\u0004ה\u0003לוים בהדי הדדי כתיב\u0004 \u0005[ביחד נאמרה]!\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 הכתוב, כך יש לקוראו\u0005]:\u0006 \u0003\"והחונים לפני המשכן קדמה לפני אהל מועד מזרחה\u0004 — \u0003משה\",\u0004 ולמדים מכאן שהלויים שומרים במקדש, \u0003והדר\u0004 \u0005[וחזר]\u0006 ואמר הכתוב \u0003\"אהרן ובניו שומרי משמרת המקדש\"\u0004 — ומכאן למדים שהכהנים שומרים כשלעצמם, ובאופן זה: \u0003\"אהרן\"\u0004 — \u0003בחד מקום\u0004 \u0005[במקום אחד],\u0006 \u0003\"ובניו\"\u0004 — \u0003ב\u0004עוד \u0003שני מקומות,\u0004 והרי אלה שלשה מקומות שבהם שומרים הכהנים עצמם.","ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 שכך צריך לקרוא ולהבין את הכתוב? ומשיבים: \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 בתחילת כתוב זה לשון \u0003\"והחונים\" ו\u0004לאחר מכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 בו בלשון \u0003\"שומרים\"\u0004 — הרי זה מלמד כי מדובר בשתי קבוצות נפרדות, אלו המכונים בכתוב \u0003\"חונים\" לחוד\u0004 \u0005[לעצמם],\u0006 \u0003ו\u0004אלו המכונים \u0003\"שומרים\" לחוד\u0004 \u0005[לעצמם].\u0006","ושואלים עוד: למדנו מכאן שהכהנים והלויים שומרים במקומות נפרדים, ואולם עדיין \u0003אימא\u0004 \u0005[אמור]\u0006 שהכהנים \u0003כולהו בחד מקום לחודיה\u0004 \u0005[כולם,\u0006 שומרים \u0005במקום אחד לעצמו]!\u0006 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[אינך יכול להעלות על דעתך]\u0006 לומר כן, שהרי כתוב זה מקיש את משה לאהרן ובניו, ומעתה יש לומר: \u0003מה משה\u0004 — \u0003בחד מקום לחודיה\u0004 \u0005[במקום אחד לעצמו]\u0006 הוא שומר, ולא באותו מקום בו שומר אהרן, \u0003אף אהרן ובניו\u0004 — כל אחד ואחד מהם \u0003בחד מקום לחודיה\u0004 \u0005[במקום אחד לעצמו]\u0006 הם שומרים.","\u0003רב אשי אמר,\u0004 מקור אחר יש בתורה ממנו אנו למדים כי הכהנים שומרם בשלשה מקומות, והוא \u0003מסיפיה דקרא\u0004 \u0005[מסופו של הכתוב]\u0006 הזה, שכן נאמר בכתוב \u0003\"שומרים משמרת\u0004 המקדש \u0003למשמרת\",\u0004 ושלש לשונות שמירה אלה מורות כי שלש שמירות נפרדות הן."],["שנינו במשנתנו כי \u0003בית אבטינס ובית הניצוץ\u0004 היו עליות. ובהבנת הדברים הללו \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 שאלה זו: האם הכוונה היא שבית אבטינס ובית הניצוץ עצמם \u0003עליות ממש הוו\u0004 \u0005[היו],\u0006 שהיו תחתיהן מדורים אחרים \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא שלא היה תחתיהן כל מדור אלא \u0003דהוו גביהי מגבה\u0004 \u0005[שהיו\u0006 בנויים על גבי עמודים ו\u0005גבוהים]\u0006 היו \u0003כעליות?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בא,\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה \u0003דתנן\u0004 \u0005[ששנינו]\u0006 במשנה במסכת מדות המונה את שבעת שערי העזרה ומציינת בין השאר את מקומם של שלשת השערים \u0003שבצפון\u0004 העזרה, שהם שער הניצוץ, שער הקרבן, ושער בית המוקד. ובתיאורו של \u0003שער הניצוץ\u0004 שנינו שם: \u0003כמין אכסדרא\u0004 (מבנה מקורה, הניצב על עמודים) \u0003היה,\u0004 ובשני צידיו היו עמודים, \u0003ועלייה בנויה על גבה, שהכהנים שומרים\u0004 שם \u0003מלמעלה,\u0004 בעליה, \u0003ו\u0004אילו \u0003הלוים\u0004 שומרים במקדש \u0003מלמטה,\u0004 על גבי הקרקע. \u0003ופתח היה לו\u0004 לבית הניצוץ הפונה \u0003לחול.\u0004 הרי איפוא מוכח שהיתה זו עליה ממש.","ודנים בדבר זה: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים],\u0006 מה מקורה של הלכה זו שיהיו הכהנים שומרים מלמעלה, והלויים מלמטה? \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בתורה לאהרן הכהן: \"וגם את אחיך מטה לוי שבט אביך הקרב אתך \u0003וילוו עליך וישרתוך\u0004 ואתה ובניך אתך לפני אהל העדות\" (במדבר יח, ג) — \u0003בעבודתך\u0004 זו, של שמירת המקדש, שזו העבודה היחידה במקדש שגם אתה הכהן וגם הלוי מצווים בה, \u0003הכתוב מדבר.\u0004 ובא הכתוב ללמדנו, שאין הלויים אלא כנלוים וטפלים בשמירתם לשמירת הכהנים (\"וילוו עליך\"), שאין הם שומרים כמו הכהנים בגובה המקדש, אלא בקרקעיתו.","ודנים על לימוד זה: \u0003אתה אומר\u0004 בפירוש הכתוב כי \u0003בעבודתך\u0004 של שמירת הכהנים \u0003הכתוב מדבר, או\u0004 שמא \u0003אינו\u0004 מדבר \u0003אלא\u0004 שהלויים נלוים אל הכהנים \u0003בעבודתם\u0004 של הלויים, בנשיאת כלי המשכן, וזו היא הדרך בה הם נלוים אל הכהנים. ומשיבים: \u0003כשהוא\u0004 הכתוב \u0003אומר\u0004 באותה פרשה \u0003\"ונלוו עליך ושמרו לכל כליו ולכל עבודתו\u0004 את משמרת אהל מועד לכל עבודת האהל\" (שם ד) — \u0003הרי בעבודתם\u0004 של הלויים \u0003אמור\u0004 מקרא, ויש איפוא לשאול: \u0003הא\u0004 \u0005[הרי]\u0006 מעתה \u0003מה אני מקיים\u0004 (במה אני מעמיד) את הכתוב \u0003\"וילוו עליך וישרתוך\"?\u0004 — \u0003בעבודתך\u0004 של כהונה שמשתתפים בה הלויים \u0003הכתוב מדבר. הא\u0004 \u0005[הרי]\u0006 זו, השמירה המשותפת לכהנים וללויים. ו\u0003כיצד\u0004 היא נעשית? ה\u0003כהנים\u0004 — היו \u0003שומרים מלמעלה, ו\u0004אילו ה\u0003לוים\u0004 — שומרים \u0003מלמטה. \u0004","שנינו במשנתנו כי\u0003בית המוקד\u0004 היה \u0003כיפה, ובית גדול היה,\u0004 והוא המקום השלישי בו שומרים הכהנים. ומדברי המשנה משמע שבבית המוקד כמו בשני המקומות האחרים היה רק שומר אחד.","ושואלים: \u0003ו\u0004רק \u0003חד\u0004 \u0005[אחד]\u0006 \u0003שומר הוא דהוה\u0004 \u0005[שהיה]\u0006 \u0003בבית המוקד? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו במסכת מדות: \u0003שני שערים היו בבית המוקד,\u0004 ה\u0003אחד\u0004 מהם, הנמצא בצפון בית המוקד היה \u0003פתוח לחיל\u0004 (השטח שבין העזרה להר הבית והוא חולין) \u0003ו\u0004ה\u0003אחד,\u0004 הנמצא בדרום בית המוקד היה \u0003פתוח לעזרה.\u0004 ו\u0003אמר רבי יהודה: ב\u0004שער \u0003זה ש\u0004היה פתוח לעזרה בו היו \u0003נכנסין\u0004 בכל בוקר \u0003לעזרה\u0004 — \u0003פשפש\u0004 (פתח) \u0003קטן היה לו\u0004 בתוך השער, \u0003שבו\u0004 היו \u0003נכנסין\u0004 על מנת \u0003לבלוש\u0004 (לחפש ולבדוק) את \u0003העזרה,\u0004 אם הכל מונח במקומו כראוי. ויש לשאול, כיון ששני שערים היו שם, ראוי היה שתהיינה שם שתי שמירות! \u0003אמר אביי\u0004 בתשובה: \u0003כיון דגבי הדדי הוו קיימי\u0004 \u0005[זה אצל זה היו עומדים]\u0006 שני השערים הללו — \u0003סגי להו בחד\u0004 \u0005[די להם באחד]\u0006 ה\u0003שומר\u0004 אותם, שכן השומר בשער זה הריהו \u0003דוי להכא ודוי להכא\u0004 \u0005[רואה לכאן ורואה לכאן],\u0006 ונשמרים בכך שני השערים.","ועוד שנינו במשנתנו כי בית המוקד היה \u0003מוקף\u0004 (בחלקו של חול) \u0003רובדין של אבן.\u0004 ומבררים: \u0003רובדין\u0004 אלה \u0003מאי ניהו\u0004 \u0005[מה הם,\u0006 מה טיבם\u0005]?\u0006 \u0003גזרתא דאצטבתא\u0004 \u0005[אבנים גזורות,\u0006 חצובות ומסותתות\u0005],\u0006 \u0003דסלקי בהו\u0004 \u0005[שעולים בהן\u0006 הכהנים\u0005]\u0006 \u0003לאצטבתא\u0004 \u0005[שורת אבנים בולטות]\u0006 לשכב שם. ושואלים: \u0003ומי הוו מיפלגי\u0004 \u0005[והאם היו חוצים,\u0006 גוזרים\u0005]\u0006 \u0003אבנים\u0004 בבנין המקדש? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתיאור בנין בית המקדש בימי שלמה \u0003\"והבית בהבנותו אבן שלמה\u0004 מסע נבנה ומקבות והגרזן כל כלי ברזל לא נשמע בבית בהבנותו\" (מלכים א ו, ז), ומכאן שכל אבן ואבן היתה שלמה, וכפי שהיתה בשעה שהוסעה (הובאה) ממקום מחצבתה, כך נבנתה במקדש, בלא שיונף עליה כלי ברזל לגוזרה!","\u0003אמר אביי\u0004 בתשובה: כל האיסור שלא להניף על אבני המקדש ברזל הוא רק בתוך בית המקדש עצמו (\"לא נשמע בבית\") ואולם אין כל איסור לתקן את האבנים מחוצה לו אף בברזל. וכאן מדובר באופן \u0003דמתקני ומייתי מעיקרא\u0004 \u0005[שהיו\u0006 בוני המקדש \u0005מתקנים\u0006 אותם בכלי ברזל מחוץ למקדש \u0005ומביאים מתחילה,\u0006 קודם בנייתן במקדש\u0005]\u0006 שני סוגי אבנים, \u0003אבני זוטרתא ואבני רברבתא\u0004 \u0005[אבנים קטנות ואבנים גדולות],\u0006 \u0003כדכתיב\u0004 \u0005[כנאמר]\u0006 בבנין המקדש \"ומיוסד אבנים יקרות גדולות \u0003אבני עשר אמות ואבני שמונה אמות\"\u0004 (שם ז, י), ושורת האבנים בנות עשר אמות (הבולטת שתי אמות משורת האבנים בנות שמונה האמות), היא ששימשה למשכב לכהנים.","ובעניינם של רובדי אבן אלה, שנינו עוד במשנתנו כי \u0003זקני בית אב\u0004 היו \u0003ישנים שם,\u0004 על הרובדים הללו. \u0003ו\u0004שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם ישנים על הרובדים הללו? \u0003לעיילי\u0004 \u0005[שיכניסו]\u0006 לבית המוקד \u0003מטות,\u0004 ויישנו עליהן! \u0003אמר אביי\u0004 בתשובה: אין עושים כן, כי \u0003לאו אורח ארעא\u0004 \u0005[אין\u0006 זה \u0005דרך ארץ],\u0006 \u0003לעיולי\u0004 \u0005[להכניס]\u0006 \u0003מטות לבית המקדש.\u0004","שנינו עוד במשנה כי \u0003פרחי כהונה\u0004 היו שוכבים שם על הארץ, כאשר כל \u0003איש\u0004 ואיש מהם שוכב על \u0003כסותו\u0004 שמונחת \u0003בארץ.\u0004 ומבררים: \u0003אמאי התם\u0004 \u0005[מדוע, שם,\u0006 בתחילת המשנה\u0005]\u0006 התנא \u0003קרי להו\u0004 \u0005[קורא להם,\u0006 מכנה אותם\u0005]\u0006 בשם \u0003\"רובים\"\u0004 (שכך שנינו בה ש\"הרובים שומרים שם\"), ואילו \u0003הכא קרי להו\u0004 \u0005[כאן\u0006 הוא \u0005קורא להם]\u0006"],["\u0003\"פרחי כהונה\"? אמרי\u0004 \u0005[אומרים]\u0006 חכמים בהסבר הדברים: אכן \u0003אין\u0004 \u0005[כן]\u0006 ראויים הדברים להישנות כך, וטעם הדבר, \u0003התם\u0004 \u0005[שם,\u0006 בתחילת משנתנו\u0005]\u0006 שמדובר בה בכהנים השומרים בבית אבטינס ובבית הניצוץ, ש\u0003לא מטו\u0004 \u0005[באו]\u0006 עדיין לכלל אפשרות \u0003למעבד\u0004 \u0005[לעבוד]\u0006 \u0003עבודה\u0004 במקדש שכן לא היו השומרים אלא אלה שעדיין לא הגיעו לגיל העבודה (שהרי אלה שהגיעו לכך אינם מסתפקים בשמירה אלא רוצים לעבוד עבודה גמורה) ולכך \u0003קרי להו\u0004 \u0005[קורא להם]\u0006 התנא בכינוי \u0003\"רובים\"\u0004 (נערים), ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 בהמשך משנתנו\u0005]\u0006 שמדובר בכהנים הישנים בבית המוקד, \u0003דמטו להו למעבד\u0004 \u0005[ש\u0006כבר \u0005באו להם לעבוד,\u0006 שהריהם מכלל הראויים לעבודה\u0005]\u0006 \u0003עבודה\u0004 במקדש — \u0003קרי להו\u0004 \u0005[קורא להם]\u0006 התנא בכינוי \u0003\"פרחי\u0004 כהונה\".","כדברי משנתנו (הפותחת את מסכתנו) בענין שמירת הכהנים בשלושה מקומות במקדש, כך הם גם דברי המשנה הפותחת את המסכת הבאה, מסכת מידות, ושנינו שם עוד שאף הלוים היו בין שומרי המקדש. שכן \u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003בשלשה מקומות הכהנים שומרים בבית המקדש: בבית אבטינס, ובבית הניצוץ, ובבית המוקד.\u0004","\u0003והלוים\u0004 שומרים \u0003בעשרים ואחד מקומות\u0004 במקדש. וכך נתחלקו משמרות לויים אלה: \u0003חמשה\u0004 משמרות — מופקדים \u0003על\u0004 שמירתם של \u0003חמשה שערי הר הבית. ארבעה\u0004 משמרות לויים — מופקדים \u0003על\u0004 שמירת \u0003ארבע פנותיו\u0004 של הר הבית \u0003מבפנים\u0004 לחומת הר הבית. ועוד \u0003חמשה\u0004 משמרות לויים — מופקדים \u0003על\u0004 שמירתם של \u0003חמשה שערי\u0004 ה\u0003עזרה. ו\u0004עוד \u0003ארבעה\u0004 משמרות לויים — מופקדים \u0003על\u0004 שמירת \u0003ארבע פנותיו\u0004 של העזרה \u0003מבחוץ\u0004 לחומת העזרה. ומשמר \u0003אחד\u0004 של לויים — הריהו מופקד על השמירה \u0003בלשכת הקרבן\u0004 (מקום שהייתן של הבהמות העומדות להקרבה, וכבר נבדקו אם אין בהן מום הפוסלן להקרבה), \u0003ו\u0004משמר \u0003אחד\u0004 של לויים — מופקד על השמירה \u0003בלשכת הפרוכת\u0004 (מקום אריגתה של הפרוכת), \u0003ו\u0004עוד משמר \u0003אחד\u0004 של לויים — על השמירה ל\u0003אחורי בית הכפורת\u0004 (השטח שבין קודש הקדשים ובין החומה המערבית של הר הבית).","ודנים בדין זה של שמירת הלויים בעשרים ואחד מקומות במקדש: \u0003מנהני מילי\u0004 \u0005[מנין אלה הדברים,\u0006 מה מקורם בתורה\u0005]?\u0006 \u0003אמר רב יהודה מ\u0004העיר \u0003סורא,\u0004 האמורא, \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005האומרים אותה\u0006 אימרה\u0005]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא\u0006 היא \u0005שנויה],\u0006 ומדברי תנאים היא: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בחלוקה של הלויים השומרים בשערי המקדש (\"למחלקות לשוערים\", דברי הימים א, כו, א) בימי דוד (לצורך עבודתם במקדש, לכשיבנה על ידי שלמה בנו): \u0003\"למזרח הלוים ששה, לצפונה\u0004 \u0003לוים\u0004 [ליום] \u0003ארבעה, לנגבה לוים\u0004 (ליום) \u0003ארבעה, ולאסופים שנים שנים. לפרבר למערב ארבעה למסלה שנים לפרבר\u0004 (שם, יז—יח).","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתהיה על הסבר זה: והרי \u0003הני\u0004 \u0005[אלה]\u0006 משמרות הלויים המנויים במקרא זה \u0003עשרים וארבעה הוו\u0004 \u0005[היו]\u0006 מספרם הכולל (במזרח — ששה, בצפון ובדרום — ארבעה וארבעה, לאסופים — שנים ושנים שהם ארבעה, הרי אלה שמונה עשר. ועוד ששה לפרבר למערב. הרי מספרם הכולל הוא עשרים וארבעה)! \u0003אמר אביי\u0004 בהסבר הדברים: \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 הכתוב \u0005אומר,\u0006 זו כוונתו\u0005]:\u0006 \u0003לאסופים\u0004 — \u0003שנים\u0004 שהם \u0003(שנים)\u0004 בלבד, שאין זה אלא כפל לשון, כמצוי בכתובים.","ומקשים על תשובת אביי: והרי \u0003אכתי\u0004 \u0005[עדיין],\u0006 אף לפי הסבר זה, עדיין \u0003עשרין ותרי הוו\u0004 \u0005[עשרים ושנים\u0006 משמרות לויים \u0005היו],\u0006 ולא עשרים ואחד! ומתרצים: \u0003היאך\u0004 \u0005[זה]\u0006 המשמר של ה\u0003פרבר\u0004 — שומר \u0003חד הוה\u0004 \u0005[אחד\u0006 בלבד \u0005היה],\u0006 \u0003ו\u0004זה שנאמר בכתוב \"שנים לפרבר\" — כי לוי \u0003אחרינא\u0004 \u0005[אחר]\u0006 שאינו שומר, על מנת להיות עם השומר \u0003בצוותא\u0004 \u0005[ביחד]\u0006 \u0003הוא דאזיל ויתיב גביה\u0004 \u0005[שהלך וישב אצלו],\u0006 ובמה נתייחד דווקא לוי זה שהוא צריך לצוותא ולא השאר — \u0003משום דקאי אבראי\u0004 \u0005[שהיה עומד,\u0006 ניצב על משמרתו \u0005בחוץ],\u0006 ואולם בשאר המשמרות לא היה צריך צוותא שכן מקומות השמירה היו סמוכים זה לזה והיו השומרים סמוכים איפוא זה לזה.","ומבררים עוד: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב \u0003\"לפרבר\"? אמר רבה בר רב שילא:\u0004 מלה זו הריהי צירוף שתי מילים ארמיות, \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003כלפי בר\u0004 \u0005[חוץ].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: אכן \u0003לעולם עשרים וארבעה\u0004 משמרות היו אלה, \u0003כדכתיב\u0004 \u0005[כמו ש\u0006אכן \u0005נאמר]\u0006 בכתוב זה, ואולם \u0003תלתא מינייהו\u0004 \u0005[שלשה מתוכם]\u0006 — משמרות של \u0003כהנים\u0004 היו, \u0003ועשרין וחד\u0004 \u0005[ועשרים ואחד]\u0006 המשמרות האחרים — של \u0003לוים.\u0004","ותוהים על הסבר זה: \u0003והא הכא\u0004 \u0005[והרי כאן,\u0006 בכתוב זה\u0005],\u0006 משמרות \u0003לוים הוא דכתיב\u0004 \u0005[שנאמר]\u0006 בו במפורש (\"למזרח הלוים...\"), ואין הכהנים נזכרים בו, והרי איפוא שכל עשרים וארבעה המשמרות כולם היו של לויים! ומשיבים: אף הכהנים נזכרים בכתוב זה, שכן בכלל הלשון \"לויים\" האמור בו כלולים אף הכהנים, ו\u0003כ\u0004שיטת \u0003ר' יהושע בן לוי,\u0004 שכן \u0003אמר ר' יהושע בן לוי: בעשרים וארבעה מקומות\u0004 במקרא \u0003נקראו\u0004 ה\u0003כהנים \"לוים\", ו\u0004כתוב \u0003זה\u0004 הוא \u0003אחד מהן,\u0004 ויש ממנו ללמד על השאר — \u0003\"והכהנים הלוים בני צדוק\u0004 אשר שמרו את משמרת מקדשי...\" (יחזקאל מד, טו), הרי שהכהנים נקראים אף בשם \"לוים\".","ומבררים עוד דברי משנה זו שבמסכת מדות, שנינו בה כי \u0003חמשה\u0004 משמרות לויים — מופקדים \u0003על\u0004 שמירת \u0003חמשה שערי הר הבית, וארבעה\u0004 משמרות נוספים — על ארבעה פנותיו מתוכו, ועוד \u0003חמשה\u0004 משמרות — המופקדים \u0003על\u0004 שמירת \u0003חמשה שערי\u0004 ה\u0003עזרה, ו\u0004עוד \u0003ארבעה\u0004 — המופקדים \u0003על\u0004 שמירת \u0003ארבעה פנותיו מבחוץ.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 הוא \u0003הר הבית\u0004 — \u0003דעבדינן\u0004 \u0005[שעושים אנו]\u0006 את שמירתו \u0003מתוכו, ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה,\u0006 מיוחדת\u0005]\u0006 היא ה\u0003עזרה\u0004 — \u0003דעבדינן\u0004 \u0005[שעושים אנו]\u0006 את שמירתה \u0003מבחוץ?\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: בשמירת \u0003הר הבית, דאי תמה ובעי מיתב\u0004 \u0005[שאם התעייף\u0006 השומר שם מהעמידה הממושכת על רגליו, \u0005ורוצה לשבת,\u0006 לנוח\u0005]\u0006 — הריהו \u0003יתיב\u0004 \u0005[יושב],\u0006 שהרי מותרת הישיבה בהר הבית, לכך \u0003אמרינן\u0004 \u0005[אומרים אנו,\u0006 נקבעה הלכה\u0005]\u0006 כי שמירתו \u0003מתוכו.\u0004 מה שאין כן ב\u0003עזרה, דאי תמה ובעי למיתב\u0004 \u0005[שאם התעייף, ורוצה לשבת,\u0006 לנוח\u0005]\u0006 — \u0003לא מצי יתיב\u0004 \u0005[אינו יכול לשבת],\u0006 שהרי \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין\u0004 ה\u0003ישיבה בעזרה\u0004 מותרת \u0003אלא למלכי בית דוד בלבד,\u0004 לכך \u0003אמרינן\u0004 \u0005[אומרים אנו,\u0006 נקבעה הלכה\u0005]\u0006 כי שמירתו \u0003מבחוץ,\u0004 שאם יתעייף יוכל להתיישב.","עוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה זו כי \u0003חמשה\u0004 משמרות היו מופקדים \u0003על\u0004 שמירת \u0003חמשה שערי עזרה,\u0004 ותוהים: \u0003ו\u0004האם \u0003חמשה שערים הוא דהוי\u0004 \u0005[שהיו]\u0006 \u0003ב\u0004חומת \u0003עזרה?! ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במסכת מדות כי \u0003שבעה שערים היו ב\u0004חומת ה\u0003עזרה,\u0004 \u0003שלשה בצפון, ושלשה בדרום, ואחד במזרח,\u0004 ואם כן ראוי היה להעמיד משמרות בכל שבעת השערים!","\u0003אמר אביי\u0004 בתשובה: אף שאכן שבעה שערים הם, אין שומרים אלא בחמישה מהם, כי \u0003תרי מינייהו\u0004 \u0005[שניים מהם\u0006 מהשערים הללו\u0005]\u0006 שער הניצוץ ובית המוקד \u0003לא\u0004 היו \u0003צריכי\u0004 \u0005[צריכים]\u0006 \u0003שימור\u0004 על ידי משמרות לויים, שכן שמרו בהם הכהנים, כמבואר במשנתנו. \u0003רבא אמר\u0004 תירוץ אחר: אין להביא סתירה ממשנה זו לענין מספרם של שערי העזרה, כיון שמחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 באשר למספרם של השערים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בסדר המינויים במקדש, \u0003אין פוחתין משלשה עשר גזברין ומשבעה אמרכלין. ר' נתן אומר: אין פוחתין משלשה עשר גזברין, כנגד שלשה עשר שערים\u0004 שהיו בבית המקדש. ומעתה כאשר \u0003דל\u0004 \u0005[טול,\u0006 הפחת\u0005]\u0006 ממספר זה של השערים את \u0003חמשה\u0004 השערים של \u0003הר הבית\u0004 — \u0003פשו להו תמניא\u0004 \u0005[נשארו להם שמונה]\u0006 שערים שב\u0003עזרה. אלמא\u0004 \u0005[הרי איפוא],\u0006 מכאן נלמד כי שיטות שונות יש בדבר \u0003איכא\u0004 \u0005[יש]\u0006 \u0003תנא\u0004 ש\u0003אמר\u0004 כי \u0003תמניא הוו\u0004 \u0005[שמונה\u0006 שערים \u0005היו]\u0006 בעזרה, \u0003ואיכא\u0004 \u0005[ויש]\u0006 \u0003תנא\u0004 ש\u0003אמר\u0004 כי \u0003שבעה\u0004 היו בעזרה, \u0003ואיכא\u0004 \u0005[ויש]\u0006 \u0003תנא\u0004 ש\u0003אמר\u0004 כי \u0003חמשה\u0004 שערים \u0003הוו\u0004 \u0005[היו].\u0006 ומשנתנו כשיטה שחמישה שערים היו.","ושבים לבירור דברי משנתנו, שנינו בה כי הכהנים הישנים בבית המוקד \u0003לא היו ישנים בבגדי קדש\u0004 אלא היו פושטים את בגדיהם ומקפלים אותם ומניחים אותם תחת ראשיהם. ומדייקים בדברים: דווקא מעשה \u0003שינה הוא\u0004 ש\u0003לא\u0004 עשו הכהנים בהיות בגדיהם עליהם (ומשום החשש שיפיח הישן תוך שנתו, והרי זה גנות לבגדי הכהונה שעליו), \u0003אבל\u0004 מעשה אחר הנעשה בהקיץ, וכגון ה\u0003הילוך\u0004 בבגדים הללו — היו \u0003מהלכים,\u0004 אף שאין זה לצורך עבודה במקדש. ומעתה \u0003שמעת מינה\u0004 \u0005[שומע,\u0006 לומד \u0005אתה ממנה],\u0006 כי \u0003בגדי כהונה ניתנו ליהנות בהן!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית הראיה: אין לדייק כן, שהרי ניתן לומר כי \u0003הוא הדין\u0004 ש\u0003אפילו\u0004 ה\u0003הילוך\u0004 בבגדי כהונה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 הותר לכהנים שלא לצורך עבודה, ויכול היה התנא במשנתנו להשמיענו אכן דבר חידוש גדול יותר שאף לא היו מהלכים בהם, \u0003והא דקתני\u0004 \u0005[וזה ששנינו]\u0006 כי \u0003לא היו ישנים\u0004 בהם — \u0003משום דבעי למיתנא סיפא\u0004 \u0005[שרצה\u0006 התנא \u0005לשנות\u0006 את \u0005הסוף,\u0006 את המשך דבריו\u0005]:\u0006 \u0003אלא פושטין\u0004 היו את בגדיהם \u0003ומקפלין ומניחין אותן תחת ראשיהן\u0004 לפני השינה, משום כך \u0003קתני רישא נמי\u0004 \u0005[הוא שונה תחילת\u0006 דבריו \u0005גם כן]\u0006 ש\u0003לא היו ישנים\u0004 בבגדי כהונה.","ותוהים: \u0003והא גופה קא קשיא\u0004 \u0005[והרי\u0006 לפי זה דברי המשנה \u0005עצמה קשים,\u0006 סותרים דחייה זו\u0005],\u0006 שהרי שנינו בה: \u0003ומניחין\u0004 הכהנים \u0003אותן\u0004 (את בגדי הכהונה) \u0003תחת ראשיהן,\u0004 ומשמשים איפוא הבגדים להם ככר לשינה — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בגדי כהונה ניתנו ליהנות בהם!\u0004 ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך בכוונת דברי המשנה הללו: ומניחים אותם לא תחת ראשיהם, אלא \u0003נגד ראשיהם,\u0004 מן הצד.","\u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן,\u0006 מתוך תירוץ זה\u0005]\u0006 כי כשם שמותר להניח את בגדי הכהונה בצד ראשי הכהנים הישנים, אף \u0003תפילין\u0004 שחלץ אותם אדם מעליו בשעה שהולך הוא לישון, והניחם \u0003מן הצד\u0004 לראשו, ולא תחת ראשו ממש — \u0003שריין\u0004 \u0005[מותרים]\u0006 לעשות כן, \u0003ולא חיישינן דלמא מיגנדר ונפיל עלייהו\u0004 \u0005[ואין אנו חוששים שמא יטלטל מצד לצד\u0006 תוך כדי שנתו, \u0005ויפול עליהם],\u0006 ויביאם בכך לידי גנות.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר בכוונת דברי משנתנו שמונחים בגדי הכהונה לא תחת ראשי הכהנים אלא \u0003כנגד ראשיהן, דאי אמרת\u0004 \u0005[ש\u0006כן \u0005אומר אתה]\u0006 שהניח את הבגדים \u0003תחת ראשיהן\u0004 ממש, יש להקשות: \u0003נהי\u0004 \u0005[אמנם]\u0006 אף אם נאמר כי \u0003ניתנו\u0004 בגדי כהונה \u0003ליהנות בהן,\u0004 ואולם \u0003תיפוק ליה\u0004 \u0005[יצא לו]\u0006 שאסור הדבר \u0003משום איסורא\u0004 \u0005[איסור]\u0006 \u0003כלאים\u0004 שבבגדי כהונה, שלא הותר לבישת בגדים אלה שיש בהם כלאים אלא בשעת העבודה!"],["\u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003אבנטו של כהן גדול\u0004 \u0003לא זהו אבנטו של כהן הדיוט,\u0004 שהוא אחד מארבעה בגדי כהונה של כהן הדיוט. שכן באבנטו של כהן גדול היה אכן כלאים, כמפורש בתורה שנעשה מן התכלת והארגמן ותולעת השני (שהם ממיני הצמר) ומן השש (שהוא פשתן), והרי זה בכלל כלאי בגדים. ואולם לדעתו אבנטו של כהן הדיוט (שלא נתפרש בתורה ממה נעשה) נעשה כשאר בגדיו מן השש בלבד, ולא היו בו איפוא כלאים. ולפי שיטה זו, מובן מדוע הניחו הכהנים את בגדיהם תחת ראשיהם, שהרי אין בדבר משום כלאים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003אבנטו של כהן הדיוט זהו אבנטו של כהן גדול,\u0004 ואף באבנטו של כהן הדיוט היה כלאים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בתשובה לשאלה כיצד הניחו אותם תחת ראשיהם? אלא מכאן ראיה שלא הניחום תחת ראשיהם ממש, אלא כנגד ראשיהם.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בדחייה שבאמת הניחום תחת ראשיהם, אף שיש בהם כלאים, והטעם שלא הקפידו בכך, משום ש\u0003כלאים\u0004 רק \u0003ב\u0004דרך \u0003עליה\u0004 על הגוף \u0003ולבישה הוא\u0004 ש\u0003אסור,\u0004 שכן נאמר בכתוב \"ובגד כלאים שעטנז לא יעלה עליך\" (ויקרא יט, יט), \u0003אבל מימך תותיה\u0004 \u0005[להציע אותו תחתיו\u0006 של השוכב עליו\u0005]\u0006 — \u0003שפיר דמי\u0004 כדבר \u0005[יפה,\u0006 ראוי \u0005נחשב]\u0006 הוא — \u0003ו\u0004אולם אין לומר כך, שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 על משמעות הכתוב באיסור כלאים: \u0003\"לא יעלה עליך\"\u0004 — \u0003אבל אתה מציעו תחתיך:\u0004 שכך הוא מדין תורה, \u0003אבל אמרו חכמים\u0004 ש\u0003אסור לעשות כן,\u0004 מחשש \u0003שמא תיכרך נימא\u0004 (שערה) \u0003אחת\u0004 מבגד הכלאים \u0003על בשרו\u0004 של השוכב על הבגד, ונמצא עובר על איסור תורה שמעלה מבגד כלאים על הגוף.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בהסבר הדברים, שהכהנים לא נהגו במקדש להניח כלאים תחת ראשם אלא כאשר היה \u0003מפסיק\u0004 (חוצץ) \u0003מידי\u0004 \u0005[דבר]\u0006 כלשהו בין ראשם של הכהנים לבין בגדי הכלאים שתחתיהם, באופן שלא יתכן שתיכרך נימה מבגד הכלאים על השוכב — \u0003והאמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' שמעון, אמר ר' יהושע בן לוי, אמר ר' יוסי בן שאול משום קהלא קדישא\u0004 \u0005[בשם קהילת קודש]\u0006 \u0003שבירושלים: אפילו\u0004 היו \u0003עשר מצעות\u0004 מונחות \u0003זו על גב זו, ו\u0004בגד \u0003כלאים\u0004 מונח \u0003תחתיהן\u0004 — \u0003אסור לישן עליהן,\u0004 על המצע העליון, אף שודאי שבאופן זה אין לחשוש שתיכרך נימה מבגד הכלאים על השוכב. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לא היו הבגדים תחת ראשיהם, אלא \u0003נגד ראשיהן.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למשנתנו: אכן אפשר לומר שהיו הבגדים תחת ראשיהם ממש, ואולם אין המדובר בכל בגדי הכהונה, אלא רק \u0003באותן\u0004 בגדים \u0003שאין בהן כלאים. רב אשי אמר\u0004 הסבר אחר: מדובר במשנתנו אפילו בבגדים שיש בהם כלאים, ואכן הניחום הכהנים תחת ראשיהם, ואולם אין בדבר משום איסור כלאים, שכן \u0003בגדי כהונה קשין הן,\u0004 ואין בשכיבה עליהם משום איסור. וכפי ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו של]\u0006 \u0003רב יהושע: הא נמטא גמדא דנרש\u0004 \u0005[אותו לבד קשה\u0006 של כלאים שמייצרים בעיר \u0005נרש]\u0006 — \u0003שריא\u0004 \u0005[מותר]\u0006 אף אם יש בו כלאים כיון שאינו מחמם את הלובש אותו ולא אסרה התורה אלא דבר הדומה לבגד שיש בלבישתו משום הנאה. לאחר המשא והמתן הזה לא הגענו לתשובה ברורה לשאלה האם מותר ליהנות מבגדי כהונה שלא לצורך העבודה.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003בגדי כהונה, היוצא בהן למדינה,\u0004 מחוץ למקדש — \u0003אסור. ו\u0004אילו \u0003במקדש, בין בשעת עבודה ובין שלא בשעת עבודה\u0004 — \u0003מותר.\u0004 וטעם הדבר: \u0003מפני שבגדי כהונה ניתנו ליהנות בהן.\u0004 והרי לנו ראיה מפורשת. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבגדי כהונה הותרו אף שלא בשעת עבודה.","ושואלים לגופה של ברייתא זו: \u0003ובמדינה לא\u0004 הותרו הכהנים ללבוש בגדי כהונה כלל? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בביאור מגילת תענית, שנאמר בה כי \u0003בעשרים ואחד בו\u0004 בחודש טבת — \u0003יום הר גריזים\u0004 הוא, וקבעו אותו יום שמחה ש\u0003לא למיספד\u0004 \u0005[להספיד]\u0006 בו, משום שאירעה בו תשועה לישראל. \u0003כדאיתא\u0004 \u0005[כמו שיש,\u0006 כנמצא\u0005]\u0006 \u0003ב\u0004מסכת \u0003יומא פרק \"בא לו כהן גדול (קרוב)\u0004 לקרות\" (סט, א), ולשם הקצור לא הובא כאן הדבר אלא רק ציון של מראה מקום. וכך שנינו שם: אותו יום בקשו הכותיים (שומרונים) מאלכסנדר מוקדון על המקדש להחריבו, ונתן להם רשות. ובאו והודיעו על כך לשמעון הצדיק שהיה כהן גדול באותה עת. לבש שמעון הצדיק בגדי כהונה והתעטף בבגדי כהונה, ומיקירי ירושלים היו עמו, ואבוקות של אש בידיהם. וכל הלילה היו נציגי ישראל אלה הולכים בצד זה, וצבאו של אלכסנדר היה הולך מצד זה. כיון שעלה עמוד השחר, אמר להם אלכסנדר לכותיים: מי הללו שבאים לקראתנו? אמרו לו: אלה הם היהודים שמרדו בך. כיון שהגיעו למקום הנקרא אנטיפטרס, זרחה חמה, ופגשו שני המחנות אלה באלה. כיון שראה אלכסנדר את שמעון הצדיק, ירד ממרכבתו והשתחוה לפניו. אמרו לו מלוויו: מלך גדול שכמותך ישתחוה ליהודי זה? אמר להם: יפה עושה אני כן, כי דמות דיוקנו של זה מנצחת לפני בבית מלחמתי, שכאשר אני נלחם אני רואה מעין דמות זו הולכת לפני כסימן של נצחון. אמר להם לשלוחי ישראל: למה באתם? אמרו לו: אפשר בית המקדש, מקום בו מתפללים עליך ועל מלכותך שלא תחרב, יתעוך גויים הללו להחריבו?! אמר להם: מי הם הללו? אמרו לו: כותיים הללו, הם שעומדים לפניך. אמר להם: הריהם מסורים בידכם לעשות בהם כרצונכם. מיד, נקבום בעקביהם, ותלאום בזנבי סוסיהם, והיו מגררים אותם על הקוצים ועל הברקנים, עד שהגיעו להר גריזים. כיון שהגיעו להר גריזים, ששם היה לכותיים מקדש — חרשוהו, וזרעוהו כרשינים, כסמל לחורבן גמור, ששוב אין אותו מקום ראוי עוד לבנין, כדרך שבקשו הכותיים לעשות לבית המקדש. ואותו היום נקבע כיום טוב לישראל.","וכך ממשיכה שם הגמרא \u0003עד\u0004 שהקשו שם: כיצד יצא שמעון הצדיק מחוץ למקדש כשבגדי כהונה עליו?! והשיבו, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שלא היו אלה בגדי כהונה ממש, אלא \u0003ראויין הן לבגדי כהונה,\u0004 שהיו כתבנית בגדי כהונה, אבל לא נעשו מכסף קדשים, ולא היתה בהם קדושת בגדי כהונה.","\u0003ואי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: משום שהיה זה, כדרך האמור \u0003\"עת לעשות לה' הפרו תורתך\"\u0004 (תהלים קיט, קכו), שבעת הצורך לעשות דבר לשמו של ה', מותר אף להפר דברים המפורשים בתורה, שהרי כפי שראינו היא שעמדה להם אז לישראל להצילם.","שנינו במשנתנו בדבר הכהנים הישנים במקדש בבית המוקד, שאם \u0003אירע קרי באחד מהן\u0004 הריהו יוצא והולך לו אל בית הטבילה במחילה העוברת תחת המקדש ולא בתוך המקדש עצמו.","ומעירים: מתוך זה משמע כי בניגוד למקדש עצמו המחילות שתחת הר הבית אינן קדושות, ודבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן,\u0004 שכן \u0003אמר\u0004 ר' יוחנן: ה\u0003מחילות\u0004 העוברות מתחת למקדש \u0003לא נתקדשו\u0004 כלל, לא בקדושת הר הבית ולא בקדושת העזרה. ועוד הלכה אמר ר' יוחנן בענין בעל קרי במקדש: \u0003בעל קרי\u0004 הריהו \u0003משתלח\u0004 אל מ\u0003חוץ לשני מחנות,\u0004 מחנה שכינה ומחנה לויה, ולפיכך אסור לו להשתהות בעזרה שבמקדש (מחנה שכינה) ובהר הבית (מחנה לויה).","\u0003ו\u0004עוד שנינו במשנתנו כי באותן מחילות שמתחת לבירה היו \u0003הנרות דולקין מכאן ומכאן,\u0004 והיה הכהן שנטמא מהלך לאורם עד שהגיע לבית הטבילה. ובבית הטבילה היתה דולקת מדורה, ובסמוך לבית הטבילה היה בית כסא של כבוד. ובענין זה של בית הכסא מוסרים כי \u0003רב ספרא הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003בבית הכסא, אתא\u0004 \u0005[בא]\u0006 \u0003ר' אבא\u0004 וביקש להיכנס לבית הכסא לעשות צרכיו, ומאחר ולא היתה שם דלת \u0003נחר ליה\u0004 \u0005[השמיע לו\u0006 לרב ספרא \u0005קול חרחור],\u0006 כדרך שאלה אם יכול הוא להיכנס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא: \u0003ליעול מר\u0004 \u0005[יכנס אדוני]!\u0006 שמע רב אבא ונכנס.","\u0003בתר דנפיק\u0004 \u0005[לאחר שיצא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא\u0004 לרב ספרא: \u0003עד כאן\u0004 (עדיין) \u0003לא סליקת\u0004 \u0005[עלית,\u0006 הגעת\u0005]\u0006 \u0003ל\u0004הר \u0003שעיר\u0004 (ארץ אדום) (אף שהרבה רב ספרא במסעות אל מחוץ לארץ ישראל), וכבר \u0003גמרת מילי\u0004 \u0005[למדת דברי,\u0006 דרכי\u0005]\u0006 בני \u0003שעיר\u0004 שאין בהם צניעות?! \u0003לאו הכי תנן\u0004 \u0005[האם לא כך שנינו]\u0006 בבית כסא שהיה במקדש, שנקרא \"בית כסא של כבוד\" משום שזהו כבודו — שאם בא אדם ו\u0003מצאו\u0004 כשהוא \u0003נעול\u0004 — \u0003בידוע\u0004 הוא \u0003שיש שם אדם,\u0004 ואם מצאו כשהוא פתוח — יודע הוא שאין נמצא שם אדם. ומדוע צריך לדעת זאת? \u0003למימרא\u0004 \u0005[\u0006האם לא \u0005לומר]\u0006 משום ש\u0003לא מיבעי ליה למיעל\u0004 \u0005[לא רצוי לו\u0006 למבקש לעשות צרכיו \u0005להיכנס]\u0006 כאשר אדם אחר נמצא בפנים. ולא היה לך אם כן לומר לי להיכנס בעוד אתה בתוך בית הכסא!","ומסבירים: \u0003ורב ספרא\u0004 שאמר לר' אבא להיכנס, אף שהוא היה בתוך בית הכסא, עשה כן משום ש\u0003סבר\u0004 \u0005[סבור היה]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 ר' אבא במצב \u0003מסוכן הוא\u0004 אם לא יפנה מיד. \u0003כדתניא\u0004 \u0005[כמו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: עמוד\u0004 של צואה \u0003החוזר,\u0004 שהעוצר עצמו באמצע עשיית צרכיו — \u0003מביא את האדם לידי\u0004 מחלת \u0003הדרוקן, סילון\u0004 של מי רגלים \u0003החוזר\u0004 — \u0003מביא את האדם לידי\u0004 מחלת \u0003ירקון.\u0004","ואגב כך מביאים עוד הנהגות ראויות בעשיית צרכים. שכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו],\u0006 \u0003וכן\u0004 כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרבה בריה\u0004 \u0005[בנו]:\u0006 כאשר \u0003חשיך\u0004 \u0005[החשיך\u0006 היום, בתחילת הלילה\u0005],\u0006 \u0003תקין נפשך\u0004 \u0005[\u0006השתדל ל\u0005תקן עצמך,\u0006 לעשות צרכיך\u0005].\u0006 \u0003ו\u0004כן כאשר \u0003קדים\u0004 \u0005[קדם\u0006 ובא היום\u0005] תקין נפשך\u0006 \u0005[תקן עצמך,\u0006 עשה צרכיך\u0005],\u0006 אף שאינך צריך להם באותן שעות. וטעם הדבר — שבאותם זמנים רוב האנשים נמצאים בבתיהם ותוכל לעשות צרכיך סמוך לביתך בלא לחשוש שמא יבחין בך אדם. \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא\u0004 תצטרך במשך היום לעשיית צרכים, שאם תצטרך להם ביום \u0003תרחק\u0004 לבית כסא הנמצא במקום מרוחק ותסתכן. וכאשר אתה נפנה לעשות צרכיך, בתחילה \u0003תוב\u0004 \u0005[שב]\u0006 במקום עשיית הצרכים בעודך לבוש, \u0003ו\u0004לאחר מכן \u0003גלי\u0004 \u0005[גלה,\u0006 פשוט מלבושך\u0005],\u0006 ולא תפשוט את בגדיך קודם לכן, מחמת הצניעות. ולאחר שסיימת את עשיית הצרכים, מאותה סיבה בתחילה \u0003כסי\u0004 \u0005[כסה\u0006 עצמך בלבושך\u0005]\u0006 \u0003ו\u0004רק לאחר מכן \u0003קום\u0004 \u0005[עמוד].\u0006","ועוד הדריכו חכמים אלה את בניהם בהנהגות הראויות: כאשר אתה מבקש לשתות מן הכוס, בתחילה \u0003שטוף\u0004 את הכוס, \u0003ו\u0004לאחר מכן \u0003שתי\u0004 \u0005[שתה]\u0006 ממנה. ולאחר ששתית מן הכוס, ואין אתה נזקק לה עוד, חזור ו\u0003שטוף\u0004 אותה \u0003ו\u0004לאחר מכן \u0003אחית\u0004 \u0005[הנח]\u0006 אותה במקומה כשהיא נקיה. אכן, שטיפת הכוס לאחר השתייה בה אינה אלא לאחר שתיית יין בה, \u0003ו\u0004אולם \u0003כשאתה שותה\u0004 בה \u0003מים\u0004 — אינך צריך לשטוף אותה, אלא \u0003שפוך מהן\u0004 (מהמים שנשארו בכוס, באופן שינקו המים את הכוס דרך שפיכתם, \u0003ואחר כך\u0004 אם יצטרך לכך \u0003תן לתלמידך\u0004 שישתה ממנה.","\u0003כדתניא\u0004 \u0005[כמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישתה אדם מים ויתן לתלמידו\u0004 לשתות מאותה כוס, \u0003אלא אם כן שפך מהן\u0004 לפני כן. \u0003ומעשה באחד ששתה מים ולא שפך מהן, ונתן\u0004 אותה כוס מים \u0003לתלמידו, ואותו תלמיד איסטניס\u0004 (מפונק) \u0003היה, ולא רצה לשתות\u0004 ממנה — \u0003ומת בצמא. באותה שעה אמרו\u0004 חכמים: \u0003לא ישתה אדם מים\u0004 בכוס \u0003ויתן\u0004 אותה \u0003לתלמידו\u0004 — \u0003אלא אם כן שפך מהן. רב אשי אמר: הילכך\u0004 \u0005[משום כך],\u0006 \u0003האי תלמידא דשפיך\u0004 \u0005[תלמיד זה השופך]\u0006 מים מהכוס ששתה בה רבו, ועושה זאת \u0003קמי רביה\u0004 \u0005[לפני,\u0006 בנוכחות \u0005רבו]\u0006 — \u0003לית ביה\u0004 \u0005[אין בו]\u0006 בדבר זה \u0003משום אפקירותא\u0004 \u0005[זלזול],\u0006 שהרי כך הורו חכמים.","ועוד הדריכו חכמים אלה את בניהם: \u0003כל מילי\u0004 \u0005[הדברים]\u0006 שאתה אוכל, ובתוך אכילתך הצטבר רוק בפיך, \u0003לא\u0004 (אל) \u0003תיפלוט באפי\u0004 \u0005[בפני]\u0006 \u0003רבך,\u0004 שיש בדבר משום זלזול כבוד רבך — \u0003בר מקרא\u0004 \u0005[חוץ מדלעת]\u0006 \u0003ודייסא,\u0004 וטעם הדבר שהותרה פליטתם של אלה, משום ש\u0003כפתילה\u0004 (חתיכה לוהטת) \u0003של אבר\u0004 (עופרת) הם \u0003דמו\u0004 \u0005[נחשבים],\u0006 ויש סכנה אם לא יפלטם מפיו.","תנן התם \u0005[שנינו שם,\u0006 במסכת מדות\u0005]:\u0006 \u0003איש הר הבית\u0004 (הממונה על סדרי השמירה בהר הבית) \u0003היה מחזר\u0004 בכל לילה \u0003על כל משמר ומשמר, ואבוקות\u0004 היו \u0003דולקות לפניו,\u0004 כדי שיבחינו בו אנשי המשמר שהוא קרב אליהם ויעמדו לפניו. \u0003וכל משמר שאינו עומד\u0004 מלפניו, \u0003ואומר לו איש הר הבית:\u0004"],["\u0003\"שלום עליך\"! ניכר\u0004 בו בשומר \u0003שהוא ישן,\u0004 ואינו שומר כראוי — עומד איש הר הבית ו\u0003חובטו במקלו\u0004 כעונש על כך. \u0003ו\u0004אף \u0003רשות היתה לו,\u0004 לאיש הר הבית להעניש את השומר הישן, ו\u0003לשרוף את כסותו. והם,\u0004 השומעים את קולו של השומר הנענש, \u0003אומרים\u0004 האחד לחבירו: \u0003מה\u0004 טיבו של \u0003קול\u0004 זה הנשמע \u0003בעזרה?\u0004 וחבירו משיב לו: הרי זה ה\u0003קול\u0004 של \u0003בן לוי\u0004 ה\u0003לוקה ובגדיו נשרפין\u0004 משום \u0003שישן לו על משמר. ר' אליעזר בן יעקב אומר: פעם אחת מצאו את אחי אמי\u0004 שהיה מן השומרים \u0003ישן\u0004 על משמרתו, \u0003ושרפו את כסותו.\u0004","ובענין זה \u0003אמר ר' חייא בר אבא: כי מטי\u0004 \u0005[כאשר היה מגיע]\u0006 \u0003ר' יוחנן ב\u0004תוך לימודו ל\u0003הא מתניתא\u0004 \u0005[למשנה זו],\u0006 \u0003אמר הכי\u0004 \u0005[היה אומר כך]:\u0006 \u0003אשריהם ל\u0004דורות \u0003ראשונים\u0004 (קודמים), \u0003שאפילו על אונס שינה\u0004 היו \u0003עושין דין,\u0004 כגון זה השומר בבית המקדש שישן מתוך אונס, והיה נענש על כך. ואם כן על חטא \u0003ש\u0004נעשה \u0003לא על\u0004 ידי \u0003אונס שינה\u0004 אלא בהקיץ ובמודע \u0003על אחת כמה וכמה\u0004 שהיו מענישים.","ומתוך שהוזכרה כאן דרך לתוכחה לשומרים, מוסיפים עוד בענין זה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: איזו היא דרך ישרה שיבור\u0004 (שיבחר) \u0003לו האדם\u0004 כדרך חיים? — \u0003יאהב את התוכחות,\u0004 \u0003ש\u0004כן \u0003כל זמן ש\u0004יש \u0003תוכחות\u0004 הנשמעות \u0003בעולם\u0004 מפי החכמים — \u0003נחת רוח באה לעולם, טובה וברכה באין לעולם, ורעה מסתלקת מן העולם, ש\u0004כן \u0003נאמר: \"ולמוכיחים ינעם ועליהם תבא ברכת טוב\"\u0004 (משלי כד, כה). \u0003ויש אומרים:\u0004 דרך ישרה שיבחר לו האדם בכל מהלך חייו, היא ש\u0003יחזיק באמונה יתירה\u0004 בענייני משא ומתן ויחסו לבריות, \u0003שנאמר: \"עיני בנאמני ארץ לשבת עמדי\u0004 הולך בדרך תמים הוא ישרתני\" (תהלים קא, ו).","ועוד בענין התוכחה, \u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: כל המוכיח את חבירו לשם שמים\u0004 — \u0003זוכה לחלקו של הקדוש ברוך הוא, ש\u0004כן \u0003נאמר: \"מוכיח אדם אחרי\"\u0004 (משלי כח, כג), שהמוכיח נמצא במחיצתו של הקדוש ברוך הוא (\"אחרי\"). \u0003ולא עוד, אלא ש\u0004אף \u0003מושכין עליו\u0004 מן השמים \u0003חוט של חסד, ש\u0004כן \u0003נאמר\u0004 בהמשך אותו פסוק: \u0003\"חן ימצא ממחליק לשון\".\u0004","שנינו במשנתנו שאם אדם \u0003מצאו\u0004 את בית הכסא שבהר הבית שהוא נעול הריהו \u0003יודע\u0004 שנמצא שם אדם, ואינו נכנס. ובהמשך שנינו \u0003מי שהוא רוצה לתרום את המזבח\u0004 (תרומת הדשן) הריהו משכים וטובל לפני שיבוא הממונה. ודנים בדבר, \u0003הא גופא קשיא\u0004 \u0005[זה עצמו קשה,\u0006 הרי דברי המשנה עצמה סותרים זה את זה\u0005],\u0006 שהרי \u0003אמרת\u0004 בתחילה כי \u0003מי שהוא רוצה לתרום את המזבח\u0004 — הריהו \u0003משכים וטובל עד שלא\u0004 (בטרם) \u0003יבא הממונה\u0004 על ההגרלה (פייס). \u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפייס תליא מילתא\u0004 \u0005[תלוי הדבר]\u0006 מיהו התורם, אלא כל המזדרז ומשכים הוא התורם. \u0003והדר תני\u0004 \u0005[וחזר\u0006 התנא ו\u0005שנה]\u0006 שהממונה היה אומר להם \"מי שטבל, \u0003יבא ויפייס\", אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003בפייס תליא מילתא\u0004 \u0005[תלוי הדבר]!\u0006","\u0003אמר אביי\u0004 בתשובה: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אלא \u0003כאן\u0004 שנראה שהמקדים הוא התורם — מדובר בזמן ש\u0003קודם\u0004 ה\u0003תקנה\u0004 שתיקנו חכמים להטיל פייס על כך. ואילו \u0003כאן\u0004 ששנינו כי בפייס תלוי הדבר — מדובר בזמן ש\u0003לאחר\u0004 ה\u0003תקנה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 על התקנת הפייס: \u0003בראשונה\u0004 היה נהוג כי \u0003כל מי\u0004 מן הכהנים \u0003ש\u0004היה \u0003רוצה לתרום את המזבח,\u0004 היה אכן \u0003תורם.\u0004 ו\u0003בזמן ש\u0004הרוצים לתרום את המזבח \u0003הן מרובין\u0004 — היו קובעים את הזכאי לתרום על ידי תחרות: \u0003רצין ועולין בכבש\u0004 המזבח, ו\u0003כל הקודם את חבירו\u0004 להיכנס \u0003בתוך ארבע אמות\u0004 הסמוכות לראש המזבח — \u0003זכה\u0004 במצוה זו של תרומת המזבח. ואם \u0003היו שנים שוין,\u0004 שהגיעו שניהם יחד, היה \u0003הממונה אומר להם: \"הצביעו\",\u0004 והיה מפיל גורל ביניהם, וכאשר יבואר.","\u0003ומה הן מוציאין\u0004 בשעת הצבעה זו של הפייס? — אצבע \u0003אחת או שתים\u0004 הנמנות כאחת, שהכהנים שעמדו שם היו מושיטים את אצבעותיהם, והיו מסכימים ביניהם על מספר מסויים, והיה הממונה מונה אותם שוב ושוב עד שכלה אותו מספר, ואותו אדם שכלה בו המספר הוא שזכה. \u0003ואין מוציאין גודל\u0004 (אגודל) \u0003במקדש\u0004 לצורך ההגרלה, כדי שלא יבואו לרמות על ידי כך.","כך היה הנוהג מתחילה, ואולם פעם אחת אירע \u0003מעשה\u0004 ב\u0003שנים\u0004 כהנים ש\u0003היו שוין\u0004 בזריזות, והיו שניהם \u0003רצין ועולין בכבש, ודחף אחד מהם את חבירו,\u0004 ונפל \u0003ונשברה רגלו. וכשראו בית דין שהיו באים לידי סכנה\u0004 על ידי תחרות זו, \u0003התקינו שלא יהו תורמין את המזבח אלא בפייס\u0004 (הגרלה).","\u0003רבא אמר\u0004 תשובה אחרת לסתירה זו: \u0003אידי ואידי\u0004 \u0005[זה וזה,\u0006 בשני חלקי המשנה\u0005]\u0006 מדובר \u0003לאחר\u0004 ה\u0003תקנה\u0004 של הפייס, \u0003והכי קתני\u0004 \u0005[וכך שנויה,\u0006 זו כוונת משנתנו\u0005]:\u0006 \u0003מי שהוא רוצה לבא ולפייס\u0004 — \u0003משכים וטובל עד שלא יבא הממונה\u0004 ואז יוכל להיות בין המועמדים לתרום את הדשן.","עם עלות השחר בכל יום \u0003נטל\u0004 הממונה \u0003את המפתח\u0004 הנמצא בחלל רצפת בית המוקד מתחת לטבלה של שיש \u0003ופתח\u0004 בו \u0003את הפשפש\u0004 (פתח קטן) הנמצא בתוך שער בית המוקד, \u0003ונכנס\u0004 הממונה דרכו \u0003מבית המוקד לעזרה, ונכנסו\u0004 שאר \u0003הכהנים\u0004 בני אותו משמר \u0003אחריו, ושתי אבוקות של אור\u0004 (אש) נתונות \u0003בידם,\u0004 להאיר את דרכם.","ו\u0003נחלקו\u0004 הכהנים \u0003לשתי כיתות\u0004 (קבוצות), \u0003אלו\u0004 היו \u0003מהלכין באכסדרה\u0004 (רחבה מקורה על גבי עמודים המקיפה את כל העזרה מבפנים) \u0003דרך\u0004 ה\u0003מזרח, ואלו\u0004 היו \u0003מהלכין באכסדרה דרך\u0004 ה\u0003מערב,\u0004 כדי לבדוק אם כל כלי השרת נמצאים במקומם, לקראת העבודה בהם. ו\u0003היו בודקין והולכים עד ש\u0004הם \u0003מגיעים למקום\u0004 של \u0003עושה\u0004 ה\u0003חביתים\u0004 שהיה מכין את מנחת החביתים של כהן גדול המובאת בכל יום. וכאשר \u0003הגיעו\u0004 שתי הכתות הללו למקומו של עושה החביתים — \u0003אלו ואלו אמרו\u0004 זה לזה: \u0003\"שלום, הכל שלום\",\u0004 הכל על תיקונו בשלימות. ולאחר מכן \u0003העמידו\u0004 את \u0003עושה\u0004 ה\u0003חביתים לעשות חביתים.\u0004","\u0003מי שזכה\u0004 בגורל \u0003לתרום את המזבח הוא יתרום\u0004 עתה את המזבח. והוא נוטל את המחתה כדי לתרום בה את המזבח, \u0003והם,\u0004 הכהנים האחרים שבאותו בית אב \u0003אומרים\u0004 לו: \u0003הוי זהיר שלא תגע בכלי\u0004 זה שינתן בידך \u0003עד\u0004 (טרם) \u0003שתקדש\u0004 (תרחץ) \u0003ידיך ורגליך מן הכיור,\u0004 שהרי אין עובדים במקדש ללא קידוש ידים ורגלים תחילה. \u0003והרי\u0004 לך עוד לדעת כי \u0003המחתה\u0004 המשמשת לתרומת הדשן \u0003נתונה במקצוע\u0004 (בפינה) ש\u0003בין הכבש למזבח, ב\u0004צד \u0003מערבו של כבש.\u0004","\u0003אין אדם נכנס עמו,\u0004 עם הכהן התורם את המזבח, שכן אין אדם רשאי להימצא בין האולם ולמזבח אלא בשעת עבודה. \u0003ולא\u0004 היה \u0003נר בידו\u0004 של התורם בשעה שהולך לתרום את המזבח, \u0003אלא מהלך\u0004 היה \u0003לאור\u0004 עצי \u0003המערכה\u0004 הדולקים על המזבח, שהוקטרו עליהם במהלך הלילה אימורי קרבנות יום אתמול. ואף \u0003לא היו רואין אותו\u0004 בשעה שהוא הולך לקדש ידיו ורגליו, שכן הם היו במזרח העזרה והמזבח, ואילו הוא מקדש ידיו ורגליו במערבו של המזבח, והיה איפוא המזבח חוצץ ביניהם."],["","","","","","\u0003ו\u0004אף \u0003לא היו שומעין\u0004 באותה שעה \u0003את קולו,\u0004 וכך לא היו מודעים למעשיו \u0003עד שהיו שומעין\u0004 את \u0003קול\u0004 גלגל \u0003העץ\u0004 אליו היה הכיור קשור. \u0003שעשה בן קטין מוכני\u0004 (מתקן מיכני) בעל גלגל שנועד \u0003ל\u0004שקע את ה\u0003כיור\u0004 בלילה לתוך בור מים, על מנת שלא יפסלו מימי הכיור בלינה. \u0003ו\u0004כשהם שומעים את קולו של הגלגל בשעה שמעלים את הכיור מן הבור, \u0003הן אומרים\u0004 זה לזה: \u0003הגיע עת\u0004 (זמן קידוש ידים ורגלים)! ולאחר שהועלה הכיור, \u0003קידש\u0004 (רחץ) הכהן את \u0003ידיו ו\u0004את \u0003רגליו מן הכיור,\u0004 ולאחר מכן \u0003נטל\u0004 בידו את \u0003מחתת הכסף\u0004 המונחת בפינה שבין הכבש למזבח \u0003ועלה לראש המזבח.\u0004 ובתחילה הוא \u0003פינה את הגחלים הילך\u0004 והילך (לכאן ולכאן), ולאחר מכן הריהו \u0003חותה\u0004 (לוקח במחתה) \u0003את\u0004 הגחלים \u0003המאוכלות\u0004 (השרופות ביותר) מאלה \u0003הפנימיות\u0004 (שהיו בעומק הלהבה). לאחר מכן \u0003ירד\u0004 בכבש מן המזבח ו\u0003הגיע לרצפה\u0004 של העזרה בדרום מזרח. ומשם \u0003הפך\u0004 (הפנה) את \u0003פניו\u0004 במזרח לעבר \u0003צפון\u0004 העזרה. והיה \u0003הולך\u0004 בעזרה \u0003ב\u0004צד \u0003מזרחו של\u0004 ה\u0003כבש\u0004 לכיוון הכותל הדרומי של המזבח, מהלך שאורכו \u0003כעשר אמות\u0004 מתחתית הכבש, שהוא רחוק עדיין כעשרים אמה מהמזבח עצמו. וכשהגיע לשם, \u0003צבר\u0004 (בערימה) \u0003את הגחלים\u0004 שבמחתה שבידו \u0003על גבי הרצפה\u0004 במקום שהוא \u0003רחוק מן הכבש שלשה טפחים,\u0004 והוא ה\u0003מקום ש\u0004בו היו \u0003נותנים\u0004 את \u0003מוראת\u0004 (זפק) קרבן עולת \u0003העוף, ו\u0004את \u0003דישון\u0004 (האפר) ה\u0003מזבח הפנימי\u0004 (מזבח הזהב), \u0003ו\u0004את \u0003דישון המנורה.\u0004 שנינו במשנתנו ששתי כתות הכהנים הבודקות אם כל כלי השרת נמצאים במקומם בעזרה היו הולכות לשם כך באכסדרה. ותמהים: \u0003ומי הוו\u0004 \u0005[והאם היו]\u0006 \u0003אכסדראות\u0004 עץ \u0003בעזרה\u0004 (שמניחים שאכסדראות אלה היו כרוב אכסדראות עשויות עץ)? \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: מנין שאין עושין אכסדראות\u0004 עץ \u0003בעזרה?\u0004 — \u0003תלמוד לומר: \"לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך\u0004 אשר תעשה לך\" (דברים טז, כא), ו \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 הכתוב, \u0005אומר]\u0006 כך צריך להבינו: \u0003לא תטע לך אשרה\u0004 (עץ המשמש לעבודה זרה) — והרי זה איסור אחד הנזכר בכתוב. ועוד נאמר בו \u0003לא תטע לך\u0004 ולא תעשה \u0003כל עץ\u0004 שהוא, \u0003אצל מזבח ה' אלהיך\u0004 — והרי זה איסור שני הנזכר בכתוב! \u0003אמר רב חסדא\u0004 בתשובה: אין המדובר במשנתנו באכסדראות העשויות מעץ, אלא \u0003באכסדראות של בנין\u0004 הבנויות אבן, שעמודיהן ותקרתן היו מאבן.","","","","עוד שנינו במשנתנו ש\u0003היו\u0004 שתי כתות הכהנים הללו \u0003בודקין והולכין\u0004 עד שהגיעו אל מקום בית עושה החביתים, ולאחר שוידאו כי כל כלי השרת נמצאים במקומם, העמידו את עושה החביתים לעשות חביתים. ושואלים: \u0003למימרא\u0004 \u0005[האם\u0006 יש \u0003לומר\u0004 מכאן\u0005]\u0006 שעשיית ה\u0003חביתין הוו קדימי\u0004 \u0005[היו קודמים]\u0006 לכל עבודות היום שבמקדש? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין שאין דבר\u0004 עבודה במקדש \u0003קודם ל\u0004עבודת ה\u0003תמיד של שחר?\u0004 — \u0003תלמוד לומר:\u0004 \"...ובער עליה הכהן עצים בבוקר בבוקר \u0003וערך עליה העולה\u0004 והקטיר עליה חלבי השלמים\" (ויקרא ו, ה), \u0003ואמר רבה\u0004 בפירוש דברי הכתוב: הרי הקרבן נקרא בכתוב זה \u0003\"העולה\",\u0004 ובתוספת ה\"א מיידעת — להורות על חשיבותה, לפי שהיא ה\u0003עולה\u0004 הזו \u0003ראשונה\u0004 לעבודת המקדש בכל יום! \u0003אמר רב יהודה\u0004 בתשובה: אין כוונת דברי משנתנו לומר שהיו בתחילה עושים חביתים באותה שעה, אלא שהעמידו אנשים על מנת \u0003להחם\u0004 מים \u0003חמין ל\u0004צורך עשיית ה\u0003רביכה\u0004 הנחוצה לעשיית החביתים מאוחר יותר. בשעה ש\u0003ראוהו אחיו\u0004 (שאר בני בית האב של משמרת הכהנים) של הכהן התורם את המזבח \u0003שירד\u0004 מהמזבח עם מחתת הגחלים בידו, \u0003ו\u0004אזי \u0003הם\u0004 היו \u0003רצים ובאים\u0004 אל הכיור, כדי לקדש (לרחוץ) ידיהם ורגליהם בו. ולאחר ש\u0003מהרו וקדשו ידיהם ורגליהם מן הכיור, נטלו\u0004 לידיהם \u0003את המגרפות\u0004 (כלי גריפה) \u0003ואת הצינורות\u0004 (מזלגות) \u0003ועלו\u0004 עם הכלים הללו \u0003לראש המזבח,\u0004 כדי לגרוף את הדשן במגרפה למרכז המזבח (ל\"תפוח\"), ולסלק מן המזבח את האיברים שלא נתאכלו באמצעות המזלגות. ובתחילה סילקו את \u0003האברים\u0004 של קרבנות העולה \u0003והפדרים\u0004 (החלבים) \u0003שלא נתעכלו\u0004 (נשרפו ונעשו אפר) \u0003מבערב\u0004 ועד לשעה זו. ולהיכן היו מפנים אותם? — \u0003סולקין אותן\u0004 על ידי הצינורות הללו \u0003על\u0004 (אל) \u0003צדי המזבח,\u0004 ו\u0003אם אין\u0004 ה\u0003צדדים\u0004 הללו \u0003מחזיקין\u0004 (יכולים להכיל) אותם — \u0003סודרים אותם\u0004 כנגד חלק המזבח המכונה \u0003\"סובב\" על הכבש\u0004 של המזבח. ולאחר מכן \u0003החלו מעלין ב\u0004מגרפות שבידיהם את ה\u0003אפר\u0004 שבמזבח \u0003על גב תפוח\u0004 (מדרגה העשויה כעין חצי כדור) של אפר. שכן \u0003תפוח היה באמצע המזבח,\u0004 ולשם היו מכנסים את האפר שעל המזבח. ו\u0003פעמים שהיו עליו\u0004 אפר ששיעורו \u0003כשלש מאות כור.\u0004 וכאשר היתה ערימת אפר זו שבתפוח גדולה ביותר, היו מפנים אותה אל מחוץ לעיר, \u0003ו\u0004אולם \u0003ברגלים לא היו מדשנין אותו\u0004 (מורידים את הדשן מהמזבח), \u0003מפני שהוא\u0004 מוסיף \u0003נוי למזבח\u0004 שנראה לכל כמי שהקריבו עליו קרבנות רבים. \u0003ו\u0004מוסיפים כי אף כשהיה על המזבח דשן רב, וכגון בשלשת הרגלים מכל מקום \u0003מימיו\u0004"],["\u0003לא נתעצל הכהן\u0004 שהוטל עליו לעשות כן \u0003מלהוציא את הדשן\u0004 אל מחוץ לעיר.","ולאחר שהועבר האפר לתפוח, והתפנה מקום במזבח, \u0003החלו\u0004 הכהנים \u0003מעלין ב\u0004ידיהם \u0003גזירין\u0004 של עץ כדי \u0003לסדר את המערכה\u0004 (מערכה מסודרת של עצים העומדים להבערה על המזבח). ושואלים: \u0003וכי כל העצים כשרין למערכה הן?\u0004 ומשיבים: אכן \u0003כל\u0004 מיני \u0003העצים כשרין\u0004 \u0003ל\u0004שמש ב\u0003מערכה\u0004 שעל המזבח, \u0003חוץ\u0004 \u0003מ\u0004גזרי עצים \u0003של\u0004 עץ ה\u0003גפן ושל\u0004 עץ ה\u0003זית. אבל\u0004 אף שרוב מיני העצים כשרים למערכה, מכל מקום דווקא \u0003ב\u0004גיזרי עצים \u0003אלו היו רגילין\u0004 להביא: \u0003במרביות\u0004 (ענפים צעירים) \u0003של\u0004 עץ ה\u0003תאנה,\u0004 ו\u0003של\u0004 עץ ה\u0003אגוז,\u0004 \u0003ושל עץ שמן.\u0004","וממשיכים בסדר העבודה: אותו כהן שזכה בתרומת הדשן, הוא זה ש\u0003סידר את המערכה גדולה\u0004 (שעליה היו מקריבים את קרבן התמיד ואת אימורי שאר הקרבנות) בצד \u0003מזרחה\u0004 של המזבח, \u0003וחזיתה\u0004 של מערכה זו פונה אף הוא כלפי צד \u0003מזרחה\u0004 של המזבח. \u0003וראשי\u0004 (קצות) ה\u0003גזירין הפנימים\u0004 (הפונים אל תוך המזבח, לצד מערבו של המזבח) \u0003היו\u0004 ארוכים עד שהיו \u0003נוגעין בתפוח\u0004 הנמצא באמצע המזבח. \u0003וריוח היה\u0004 מניח הכהן המסדר את המערכה \u0003בין הגזירים, ש\u0004כן \u0003היו מציתים את האליתא\u0004 (הקיסמים הדקים) \u0003משם,\u0004 ברווח שבין הגזירים. שבתחילה הדליקו את הקיסמים הדקים שבין גיזרי העצים הגדולים, ומשם עברה האש אל הגזרים הללו.","\u0003בררו משם\u0004 (מבין גיזרי העצים המיועדים למערכה) \u0003עצי תאנה יפים,\u0004 שמעלתם שהם נעשים בשריפתם גחלים ולא אפר, והכהן \u0003סידר את המערכה\u0004 ה\u0003שניה\u0004 המיועדת \u0003ל\u0004עשיית ה\u0003קטורת,\u0004 שממנה לוקחים גחלי אש למזבח הקטורת שבהיכל, להקטיר עליהם את הקטורת. ומקומה של מערכה זו הריהו \u0003כנגד\u0004 הפינה ה\u0003מערבית דרומית\u0004 של מזבח העולה, בסמוך לכבש, \u0003משוך מן הקרן\u0004 המערבית דרומית \u0003כלפי\u0004 צד צפון ארבע אמות. וכמות העצים שסודרו במערכה זו, היה","\u0003ב\u0004התאם ל\u0003עומד\u0004 (אומד, הערכה) לכמה עצים נזקקים על מנת שיהיו מהם לאחר שריפתם כדי שיעור \u0003חמש סאין גחלים. ובשבת\u0004 — היתה כמות העצים של מערכה זו \u0003בעומד\u0004 (אומד) שיהיה בהם לאחר שריפתם כשיעור \u0003שמונה סאין גחלים.\u0004 והטעם לכך שהוסיפו בשבת שלשה סאים גחלים: \u0003ש\u0004כן \u0003שם,\u0004 על הגחלים הללו, \u0003היו נותנים\u0004 את הלבונה שב\u0003שני בזיכי\u0004 ה\u0003לבונה של לחם הפנים\u0004 המוקטרים בכל שבת. ואותם \u0003האברים והפדרים שלא (היו) נתעכלו מבערב,\u0004 ששנינו בתחילת המשנה שהיו מסלקים אותם לצידי המזבח, עתה היו \u0003מחזירין אותן ל\u0004צידה של ה\u0003מערכה\u0004 הגדולה, על מנת שיישרפו בה. \u0003ו\u0004אזי, \u0003הציתו\u0004 הכהנים את \u0003שתי\u0004 ה\u0003מערכות\u0004 הללו (מערכה גדולה, ומערכת הקטורת) \u0003באש,\u0004 ולאחר מכן \u0003ירדו\u0004 מהמזבח \u0003ובאו להם ללשכת הגזית\u0004 על מנת לערוך פייס באשר למי שיעבוד את העבודות הבאות.","שנינו במשנתנו כי באמצע המזבח היתה ערימת אפר עגולה שצורתה כעין תפוח, ופעמים שהיה בה אפר בשיעור שלש מאות כור. ועל שיעור זה \u0003אמר רבא:\u0004 אין זו לשון מכוונת בדיוקה, אלא הריהי לשון \u0003גוזמא\u0004 (הפלגה מרובה) ועניינה לומר שהיתה גדולה ביותר, ואולם מעולם לא היה בה בתפוח שיעור כזה. וכן על זו ששנינו בפרק הבא כי לפני שחיטתו \u0003השקו\u0004 \u0003את\u0004 קרבן \u0003התמיד\u0004 מים \u0003בכוס של זהב,\u0004 כדי להקל בכך על פשיטת עורו לאחר השחיטה, \u0003אמר רבא:\u0004 הרי זו לשון \u0003גוזמא,\u0004 שלא היתה זו כוס של זהב.","ועוד בענין זה של שימוש לשון שאינו מכוון כדיוקו, \u0003אמר ר' אמי:\u0004 יש ו\u0003דברה תורה לשון הבאי\u0004 (גוזמה), וכמו כן יש ו\u0003דברו נביאים לשון הבאי,\u0004 וכיוצא בו פעמים \u0003דברו חכמים לשון הבאי.\u0004","ומפרטים: \u0003דברה תורה לשון הבאי\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"שמע ישראל אתה עובר היום את הירדן לבוא לרשת גוים גדולים ועצומים ממך ערים גדולות ובצורות בשמים\" (דברים ט, א), ויש לשאול: וכי \u0003בשמים סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003אלא\u0004 הרי זו לשון \u0003גוזמא.\u0004","וכמו כן יש ו\u0003דברו חכמים לשון הבאי\u0004 — כגון \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 במשנתנו שב\u0003תפוח\u0004 שהיה באמצע המזבח היו לפעמים כשלש מאות כור אפר, \u0003ו\u0004כגון זו ששנינו בפרק הבא כי \u0003השקו את התמיד בכוס של זהב.\u0004","וכיוצא בדבר יש ו\u0003דברו נביאים לשון הבאי\u0004 — כגון זה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בתיאור המלכת שלמה המלך \"ויעלו כל העם אחריו \u0003(וכל עם הארץ)\u0004 והעם \u0003מחללים בחלילים\u0004 ושמחים שמחה גדולה \u0003ותבקע הארץ\u0004 ב\u0003קולם\"\u0004 (מלכים א א, מ), שבא רק להורות על גודל הקול ובודאי לא נבקעה הארץ למשמע קול זה.","ועוד בענין זה, \u0003אמר ר' ינאי בר נחמני, אמר שמואל: בשלשה מקומות דברו חכמים בלשון הבאי, ואלו הן: תפוח, גפן ופרכת\u0004 (וכאשר יפורטו בהמשך), ומעירים: הרי דבריו אלה של שמואל באים","\u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005] מ\u0006דבריו של \u0003רבא, דתנן\u0004 \u0005[ששנינו\u0006 ששנינו\u0005]\u0006 בפרק הבא כי \u0003השקו את התמיד בכוס של זהב, ואמר\u0004 על כך \u0003רבא\u0004 שזו לשון \u0003גוזמא,\u0004 לכך \u0003קא משמע לן\u0004 \u0005[\u0006שמואל \u0005משמיע לנו]\u0006 כי \u0003הני\u0004 \u0005[אלה]\u0006 השלשה — \u0003אין\u0004 \u0005[כן]\u0006 יש בהם לשון גוזמה, ואולם \u0003התם\u0004 \u0005[שם],\u0006 בהשקיית קרבן התמיד בכוס של זהב — \u0003לא\u0004 דברו חכמים בלשון גוזמה, אלא אכן כך היה, וטעם הדבר: לפי ש\u0003אין\u0004 נוהגים מנהגי \u0003עניות במקום עשירות,\u0004 ולכן בבית המקדש השתמשו בזהב ממש, אף לצורך פשוט זה.","ומפרטים את שלושת המקומות בהם אחזו חכמים לשון גוזמה, לשיטת שמואל: \u0003תפוח\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו\u0006 במשנתנו\u0005],\u0006 וכדברי רבא ור' אמי, שלא היו בו שלש מאות כור, אלא לשון גוזמה היא. \u0003גפן\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 צורה כעין \u0003גפן\u0004 העשויה \u0003זהב היתה עומדת\u0004 באולם המקדש \u0003על פתח ההיכל, ומודלה\u0004 (ומורמת ונמשכת) היתה \u0003על גבי כלונסות\u0004 (מוטות), וכל מי שהיה \u0003מתנדב\u0004 (נודב) למקדש זהב בצורת \u0003עלה\u0004"],["\u0003או\u0004 בשיעור גדול יותר, כ\u0003גרגיר\u0004 (ענבה יחידה), \u0003או\u0004 שיעור גדול יותר כעין \u0003אשכול\u0004 ענבים — היה \u0003מביא\u0004 למקדש, \u0003ו\u0004היה הכהן \u0003תולה\u0004 אותה תרומה \u0003בה,\u0004 בצורת גפן זו. ועל כך \u0003אמר ר' אלעזר בר' צדוק: מעשה היה\u0004 במקדש, \u0003ו\u0004כה גדולה וכבדה היתה גפן זהב זו, עד שהיה צורך ש\u0003נמנו עליה שלש מאות כהנים\u0004 כדי \u0003לפנותה\u0004 ממקומה למקום אחר, ליטול את כל הזהב שבה. והרי זו לשון גוזמה, הבא להורות שהיה בה זהב רב מאוד, ואולם לא בשיעור זה של משא שלש מאות כהנים.","\u0003פרוכת,\u0004 מה עניינה? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 \u0003רבן שמעון בן גמליאל אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון הסגן\u0004 (סגן הכהנים): ה\u0003פרוכת\u0004 שבמקדש היה \u0003עביה\u0004 כשיעור \u0003טפח,\u0004 ו\u0003על שבעים ושנים נימין\u0004 (חוטי שתי) היתה \u0003נארגת, ועל כל נימה ונימה\u0004 מאותן שבעים ושתים נדרשו \u0003עשרים וארבעה חוטין\u0004 כדי לעשותה, שכן היתה הפרוכת עשויה מארבעה מינים: תכלת, ארגמן, תולעת שני, ושש. וחוטו של כל אחד מארבעת אלה היה כפול ששה חוטים.","ומדותיה של הפרוכת: \u0003ארכה\u0004 היה \u0003ארבעים אמה,\u0004 כגובהו של פתח האולם שהיה גבוה ארבעים אמה, \u0003ורחבה\u0004 היה \u0003עשרים אמה,\u0004 כרוחבו של פתח האולם. \u0003ומשמונים ושתים ריבוא\u0004 דינרים היתה \u0003נעשית, ושתים\u0004 פרוכות חדשות היו \u0003עושין בכל שנה ושנה, ו\u0004כה כבדה היתה הפרוכת עד שהוצרכו ל\u0003שלש מאות כהנים\u0004 לשאתה כשהיו \u0003מטבילין אותה\u0004 ואף זו לשון גוזמה הבאה להורות שהיתה כבדה מאד, ואולם לא בשיעור זה של משא שלש מאות כהנים.","שנינו במשנתנו כי הכהנים \u0003החלו מעלין בגזירין לסדר את\u0004 אש \u0003המערכה\u0004 הגדולה. ולאחר מכן שנינו כי כל העצים ראויים לשמש כעצי המערכה, \u0003חוץ משל זית ומשל גפן,\u0004 אבל היו רגילים להשתמש במורביות של עצי תאנה, אגוז ועץ שמן. ושואלים: \u0003הני מאי טעמא\u0004 \u0005[אלה,\u0006 זית וגפן, \u0005מה טעם]\u0006 אסורים בשימוש לעצי המערכה? \u0003רב פפא אמר:\u0004 טעם הדבר, \u0003משום דקטרי\u0004 \u0005[ש\u0006יש בהם בעצי הזית והגפן \u0005קשרים,\u0006 מקומות מעובים\u0005]\u0006 שבהם תלוי הענף, ובשריפתם הם גורמים לעשן מרובה. רב אחא בר יעקב אמר: אף כי אכן עיקר הטעם הוא משום הקשרים מכל מקום נוסף טעם בדבר, \u0003משום\u0004 הדאגה ל\u0003ישוב ארץ ישראל,\u0004 שלא למעט עצים אלה. מיתיבי \u0005[מקשים]\u0006 על כך ממה ששנינו על האמור בעצי המערכה: \"ונתנו בני אהרן אש על המזבח וערכו עצים על האש.","וערכו בני אהרן הכהנים את הנתחים את הראש ואת הפדר \u0003על העצים אשר על האש\u0004 אשר על המזבח\" (ויקרא א, ז—ח), ומהלשון \"על העצים אשר על האש\" למדו חכמים כי ב\u0003עצים הנתוכים\u0004 (הניתכים, הנשרפים כליל) \u0003להיות\u0004 כאש עצמה דבר הכתוב, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 באיזה עצים מדובר? — \u0003דוקרי\u0004 \u0005[קני]\u0006 \u0003שפוד דלא קטרי ואזלי מקטר\u0004 \u0005[שאינם\u0006 מסוג העצים \u0005ההולכים ונקשרים]\u0006 אלא חלוקים לגמרי, והרי שהטעם הוא משום הקשרים!","ושואלים עוד ממה ששנינו בברייתא בדינם של עצי המערכה: \u0003וכי כל העצים כשרים למערכה הן?\u0004 — \u0003כל העצים כשרים, חוץ מן זית וגפן. אבל באלו היו רגילין: במרביות של תאנה, ושל אגוז, ושל עץ שמן. ר' אליעזר מוסיף\u0004 על הפסולים להבאה למערכה \u0003אף של\u0004 עץ ה\u0003מייש, ושל\u0004 עץ ה\u0003אלון, ושל דקל, ושל חרוב, ושל שקמה.\u0004","ויש לשאול: \u0003בשלמא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 בטעם איסור עצי הזית ועצי הגפן שהוא \u0003משום דקטרי\u0004 \u0005[שנקשרים,\u0006 שיש בהם קשרים\u0005],\u0006 לשיטת רב פפא, יש מקום לומר כי \u0003בהא קמיפלגי\u0004 \u0005[בזה נחלקו]\u0006 תנא קמא ור' אליעזר: \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר, \u0005סבור]\u0006 כי \u0003אף על גב דלא קטרי מגואי\u0004 \u0005[אף על פי שאין\u0006 העצים הללו, המייש והאלון ושאר המנויים בדבריו, \u0005נקשרים מתוכם,\u0006 שאין בהם קשר פנימי\u0005],\u0006 \u0003כיון דקטרי מבראי\u0004 \u0005[ש\u0006הם \u0005נקשרים מבחוץ]\u0006 — \u0003לא מייתינן\u0004 \u0005[אין אנו מביאים]\u0006 מהם לעצי המערכה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 התנא הראשון \u0005סבור]\u0006 כי \u0003כיון דלא קטרי מגואי\u0004 \u0005[שאין\u0006 העצים הללו \u0005נקשרים מבפנים],\u0006 \u0003אף על גב דמבראי קטרי\u0004 \u0005[אף על פי שמבחוץ\u0006 הם \u0005נקשרים]\u0006 — \u0003מייתינן\u0004 \u0005[מביאים אנו]\u0006 מהם.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 בטעם איסור עצי הזית ועצי הגפן שהוא \u0003משום ישוב ארץ ישראל,\u0004 יש לשאול: מדוע התיר התנא הראשון את עצי ה\u0003דקל\u0004 לעצי המערכה, \u0003מי לית ביה\u0004 \u0005[האם אין בו,\u0006 בדקל\u0005]\u0006 גם כן אותו טעם שלא יקצצוהו \u0003משום ישוב ארץ ישראל?\u0004","\u0003אמר לך\u0004 \u0005[יכול לומר,\u0006 להשיב \u0005לך]\u0006 רב אחא בר יעקב על שאלה זו בשאלה דומה: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 עד שאתה מקשה עלי כך מדברי הברייתא, אפשר לשאול בדומה לכך מדברי משנתנו, ששנינו בה שהיו רגילים להביא מענפי תאנה לעצי המערכה, ואפשר לשאול: וכי \u0003תאנה לית\u0004 \u0005[אין]\u0006 לאסור את השימוש \u0003בה\u0004 לעצי המערכה \u0003משום ישוב ארץ ישראל,\u0004 ומדוע אם כן לא אסרוה?! \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]?\u0006 — שמדובר בה \u0003בתאנה דלא עבידא פירא\u0004 \u0005[שאינה עושה פירות],\u0006 ומעתה בעצי \u0003דקל\u0004 האמורים בברייתא \u0003נמי\u0004 \u0005[גם כן]\u0006 — מדובר \u0003בדלא עביד פירא\u0004 \u0005[בשאינם עושים פירות],\u0006 ומשום כך מותרים לעצי המערכה.","ותוהים: \u0003ומי איכא\u0004 \u0005[והאם ישנה]\u0006 \u0003תאנה דלא עבדא פירא\u0004 \u0005[שאינה עושה פירות]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 יש תאנה שאינה עושה פירות, ו\u0003כ\u0004דרך שאמר \u0003רחבה\u0004 על שיטת גידול של עצי תאנה. שכן \u0003אמר רחבה: מייתי תאיני חיורתא\u0004 \u0005[מביאים\u0006 נטיעות של \u0005תאנים לבנות],\u0006 שזן גרוע הוא,"],["\u0003ושייפי להו בחבלא דצבתא דסריך עליה בזרא\u0004 \u0005[ושפים אותם בחבל של דקל שנדבקים בו הזרעים],\u0006 \u0003וקברי\u0004 \u0005[וקוברים,\u0006 נוטעים\u0005]\u0006 אותה \u0003היכא דמסיק ימא\u0004 \u0005[היכן שמעלה הים]\u0006 \u0003שירטון,\u0004 ואז תאנה זו \u0003קורה\u0004 לבנין — \u0003עבדא\u0004 \u0005[עושה],\u0006 \u0003פירי\u0004 \u0005[פירות]\u0006 — \u0003לא עבדא\u0004 \u0005[עושה],\u0006 \u0003ותלת בריכי מינייהו\u0004 \u0005[ושלש בריכות,\u0006 ענפים\u0005]\u0006 ממנה \u0003לא מחזקה להו גמלא\u0004 \u0005[אין\u0006 יכול \u0005להחזיק,\u0006 לשאת \u0005אותם גשר]\u0006 שענפי תאנה זו גדולים וכבדים מאד, שכיון שאינה מגדלת פירות הרי כל כוחה הולך לענפים.","שנינו במשנתנו שהכהן שתרם את הדשן \u0003סידר את המערכה גדולה,\u0004 ועשה כעין חלון (\"חזית\") בתוך עצי המערכה, הפונה לצד מזרח. ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לעשייתה של חזית זו? ומשיבים כי בדבר זה נחלקו \u0003רב הונא ורב חסדא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כדי שתהא הרוח\u0004 המזרחית \u0003מנשבת בה\u0004 במערכה, ומלבה את האש. \u0003וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כדי שיהו מציתין את האליתא\u0004 (קיסמי העצים הדקים המונחים בין גזרי העץ הגדולים) \u0003משם,\u0004 דרך חזית זו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסברה שעשיית החזית הוא לצורך הדלקת האליתא, ממה ששנינו במשנתנו כי \u0003ריוח היה בהן בין הגזירין, שהיו מציתין את האליתא משם.\u0004 הרי שלא היו מציתים את האליתא מבעד לחזית אלא באותו ריוח! ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 הסובר כך, כי מלבד החזית שדרכה היו מציתים את האליתא, עוד \u0003מקומות\u0004 ועוד \u0003מקומות עבדי\u0004 \u0005[עשו]\u0006 בתוך עצי המערכה, שבהם היו ריוח שנועד להדלקת האליתא, על מנת להגדיל ביותר את אש המערכה. א משנה ארבעה גורלות (\"פייסות\") הוטלו במקדש בכל יום, על מנת לקבוע מי מן הכהנים יעבוד במלאכות השונות. ולאחר ששנינו למעלה עניינו של הפייס הראשון (תרומת הדשן), באים לבירור עניינו של הפייס השני.","","\u0003אמר להן הממונה\u0004 לכהנים, לאחר ששבו ללשכת הגזית: \u0003בואו והפיסו\u0004 (הגרילו) \u0003מי\u0004 יהיה הכהן \u0003השוחט\u0004 את קרבן התמיד; \u0003ומי\u0004 יהיה הכהן \u0003הזורק\u0004 את דמו של קרבן התמיד; ו\u0003מי\u0004 זה שיהיה ה\u0003מדשן\u0004 (מסיר את האפר) של ה\u0003מזבח הפנימי\u0004 (מזבח הזהב, מזבח הקטורת); ו\u0003מי\u0004 זה שיהיה ה\u0003מדשן\u0004 (מוציא את האפר והפתילות החרוכות) של \u0003המנורה;\u0004 ו\u0003מי\u0004 זה שיהיה \u0003מעלה\u0004 את ה\u0003אברים\u0004 של קרבן התמיד \u0003לכבש\u0004 שליד המזבח כדי להקטירם אחר כך.","ואגב כך מביאים את סדר חלוקת האיברים להעלותם: את \u0003הראש והרגל\u0004 (האחורית) \u0003של\u0004 צד \u0003ימין\u0004 בקרבן — מעלה כהן אחד; \u0003ו\u0004את \u0003שתי הידים\u0004 (הרגליים הקדמיות) — מעלה כהן שני; \u0003העוקץ\u0004 (חוליות השדרה האחרונות והאליה) \u0003והרגל של שמאל\u0004 — מעלה כהן שלישי; את \u0003החזה והגרה\u0004 (הצואר) ומקצת איברים פנימיים המחוברים אליו, כגון: הקנה והכבד והלב — מעלה כהן רביעי; \u0003ו\u0004את \u0003שתי\u0004 ה\u0003דפנות\u0004 (הצלעות) — מעלה כהן חמישי; ואת \u0003הקרביים\u0004 — (מעיים ושאר חלקים פנימיים) מקריב כהן ששי; \u0003ו\u0004את \u0003הסולת\u0004 של מנחת קרבן התמיד — מקריב כהן שביעי; \u0003והחביתין\u0004 (מנחה שהיה מביא הכהן הגדול בכל יום) נעשים על ידי כהן שמיני; \u0003והיין\u0004 — על ידי כהן תשיעי. ונמצא מספר כל הכהנים שזכו בפייס זה שלשה עשר (תשעה אלו המעלים את קרבן התמיד והנספחים לו, וארבעה שעסקו בשחיטה, בזריקה, בדישון המזבח הפנימי ובדישון המנורה).","עמדו הכהנים ו\u0003הפיסו,\u0004 ו\u0003זכה מי שזכה.\u0004","ולאחר מכן \u0003אמר להן\u0004 הממונה לכהנים: \u0003צאו\u0004 ועמדו על מקום גבוה במקדש, \u0003וראו\u0004 משם \u0003אם\u0004 כבר האיר היום ו\u0003הגיע זמן שחיטה,\u0004 שכן שחיטה פסולה בלילה. \u0003אם הגיע\u0004 כבר הזמן, \u0003הרואה אומר: \"ברקאי\"\u0004 — הבריק האור. ומעירים כי \u0003מתיא בן שמואל\u0004 שהיה הממונה באותו זמן על הפייסות במקדש היה חולק על דעה זו ו\u0003אומר\u0004 בלשון אחר: האם \u0003האיר פני כל המזרח עד\u0004 כדי כך \u0003שהוא\u0004 האור נראה אף \u0003בחברון\u0004 (והוא אור גדול מ\"ברקאי\")? \u0003ו\u0004אם אכן כך היה \u0003הוא\u0004 (הצופה) היה \u0003אומר: הן!\u0004 ולאחר מכן הממונה \u0003אמר להן\u0004 לכהנים: \u0003צאו והביאו לי והוציאו טלה מלשכת הטלאים\u0004 (המקום בו היו טלאים מבוקרים ממום ומוכנים להקרבה), \u0003ו\u0004מכוון אותם הממונה: \u0003הרי\u0004 (הנה, הלא היא) \u0003לשכת הטלאים\u0004 זו ה\u0003נתונה במקצוע\u0004 (פינה) ה\u0003צפונית מערבית\u0004 של אולם בית המוקד שהיה בעזרה. שכן \u0003ארבע לשכות\u0004 (חדרים) \u0003היו שם\u0004 בפינות אותו אולם, ואלו הן: \u0003אחת\u0004 — \u0003לשכת הטלאים\u0004 האמורה. \u0003ואחת\u0004 — \u0003לשכת החותמות,\u0004 ששם היו מניחים את החותמות (קבלות) שעל פיהן קיבל אדם הרוצה לקנות קרבן מן המקדש את הקרבן המתאים. והיתה לשכה זו בזוית המזרחית צפונית. \u0003ואחת\u0004 — \u0003לשכת בית המוקד,\u0004 בה היה מצויה מדורה, והתבאר עניינה בתחילת מסכתנו. \u0003ואחת\u0004 — \u0003לשכה\u0004 המצויה בזוית דרומית מזרחית \u0003ש\u0004היו \u0003עושין\u0004 (לשים ואופים) \u0003בה\u0004 את \u0003לחם הפנים.\u0004","","\u0003נכנסו\u0004 הכהנים \u0003ללשכת הכלים\u0004 (בה היו נתונים כלי השרת הנדרשים לעבודות היום), ו\u0003הוציאו משם תשעים ושלשה כלי\u0004 שרת של \u0003כסף וכלי\u0004 שרת של \u0003זהב.\u0004 ולאחר מכן \u0003השקו\u0004 מים \u0003את\u0004 הטלה העומד להיות קרב על המזבח כקרבן \u0003התמיד בכוס\u0004"],["\u0003של זהב.\u0004 ו\u0003אף על פי שהוא\u0004 (הטלה המיועד לקרבן התמיד) כבר \u0003מבוקר\u0004 (שנבדק ונמצא שאין בו מום) עוד \u0003מבערב,\u0004 כלומר, קודם לכן, שכל קרבן העומד להיקרב נבדק ארבעה ימים לפני שחיטתו — חוזרים ו\u0003מבקרין אותו\u0004 שוב \u0003לאור\u0004 ה\u0003אבוקות\u0004 שמא נפל בו מום מאז הבדיקה האחרונה.","\u0003מי\u0004 מהכהנים \u0003שזכה בדישון\u0004 ה\u0003מזבח הפנימי ו\u0004הכהן שזכה \u0003בדישון המנורה, היו מקדימין\u0004 להכין את כלי השרת הנדרשים לצורך עבודות אלה, \u0003וארבעה כלים\u0004 היו \u0003בידם,\u0004 ואלו הם: \u0003הטני והכוז ושני מפתחות\u0004 שבהם פותחים את שני מנעוליו של הפתח הקטן שבצפונו של שער ההיכל (הפשפש). ומסבירים את עניינם של ארבעת הכלים הללו: \u0003הטני\u0004 — הריהו \u0003דומה ל\u0004כלי גדול שתכולתו כדי \u0003תרקב\u0004 (שלושה קבים), והריהו עשוי \u0003של זהב\u0004 ולא היה \u0003מחזיק\u0004 אלא קביים וחצי. והכוז — הריהו \u0003דומה לקיתון\u0004 (מיכל נוזלים) \u0003גדול,\u0004 ואף הוא \u0003של זהב. ושתי מפתחות\u0004 הללו למה הם שימשו? \u0003אחד\u0004 מהם — הריהו פותח את המנעול החיצוני של הפשפש, וכיון שהיה המנעול נתון בצידה הפנימי של הדלת, נמצא \u0003שהוא\u0004 הכהן הרוצה לפתוח, היה \u0003יורד\u0004 (נכנס) לצידה הפנימי של הדלת דרך פתח קטן שהיה בה \u0003באמת\u0004 ידו עד בית \u0003השחי,\u0004 ובו היה פותח את המנעול הזה. \u0003ו\u0004עוד מפתח \u0003אחד\u0004 — זה \u0003שהוא פותח\u0004 בו את המנעול בדלת הפנימית של התא שלפנים מן הפשפש, ממנה נכנס להיכל, ואותה היה פותח, \u0003כיון\u0004 (ישר).","אותו כהן שהצטווה לפתוח את שער ההיכל \u0003בא לו לפשפש\u0004 (הפתח הקטן) שהיה בצד \u0003הצפוני\u0004 של השער. שכן \u0003שני פשפשין היו לו לשער הגדול\u0004 (שער ההיכל), \u0003אחת בצפון\u0004 בימינו של השער, \u0003ואחת בדרום,\u0004 בשמאלו של השער. בפשפש זה \u0003שבדרום לא נכנס בו אדם\u0004 מעולם, ו\u0003עליו הוא מפורש על ידי יחזקאל\u0004 הנביא, שראוי לו שיהיה סגור, \u0003ש\u0004כן \u0003נאמר:\u0004 \"וישב אותי דרך שער המקדש החיצון הפונה קדים והוא סגור. \u0003ויאמר אלי ה' השער הזה סגור יהיה לא יפתח ואיש אל יבא בו כי ה' אלהי ישראל בא בו והיה סגור\"\u0004 (יחזקאל מד, א—ב).","\u0003נטל את המפתח ופתח\u0004 בו \u0003את הפשפש\u0004 שבצד צפונו של השער, \u0003ונכנס להתא\u0004 (הלשכה שלפני ההיכל), \u0003ומהתא\u0004 נכנס \u0003להיכל, עד ש\u0004הוא \u0003מגיע\u0004 מתוך ההיכל \u0003לשער הגדול. הגיע לשער הגדול,\u0004 שהיה נעול מבפנים, מה עשה? \u0003העביר את הנגר\u0004 (הבריח) \u0003ואת הפותחות\u0004 (מנעולים) ופתחו. ו\u0003לא היה שוחט ה\u0004כהן ה\u0003שוחט\u0004 את קרבן התמיד \u0003עד ש\u0004היה \u0003שומע\u0004 את קולו של ה\u0003שער\u0004 ה\u0003גדול\u0004 בשעה \u0003שנפתח.\u0004 ונשמע קול זה למרחקים, עד שאף \u0003מ\u0004העיר \u0003יריחו היו שומעין\u0004 את \u0003קול\u0004 ה\u0003שער\u0004 ה\u0003גדול\u0004 בשעה \u0003שנפתח.\u0004 ועוד זאת נמסר כי \u0003מיריחו היו שומעין\u0004 את \u0003קול\u0004 ה\u0003מגריפה\u0004 (כלי נגינה שבמקדש), \u0003מיריחו היו שומעין\u0004 את \u0003קול השיר\u0004 שהיו שרים הלויים בבית המקדש. ועוד, \u0003מיריחו היו שומעין\u0004 את ה\u0003קול\u0004 של \u0003בן ארזה\u0004 שהיה ממונה בבית המקדש על הצלצל (כלי נגינה) ה\u0003מקיש בצלצל,\u0004 והלויים היו עונים אחריו בשיר. ועוד, \u0003מיריחו היו שומעין\u0004 את \u0003קול החליל\u0004 המנגן לפני המזבח בשנים עשר ימים בשנה.","ועוד, \u0003מיריחו היו שומעין\u0004 את ה\u0003קול\u0004 של הכהן \u0003גביני\u0004 שהיה \u0003כרוז\u0004 במקדש, שהיה עומד ומכריז בכל בוקר \"עמדו כהנים לעבודתכם ולויים לדוכנכם וישראל למעמדכם\". ועוד, \u0003מיריחו היו שומעין\u0004 את \u0003קול העץ שעשה בן קטין\u0004 לשמש כ\u0003מוכני לכיור,\u0004 וכדרך שהתבאר עניינו למעלה (כח,ב). ועוד, \u0003מיריחו היו שומעין\u0004 את \u0003קול השיר\u0004 ששרו הלויים במקדש. ועוד, \u0003מיריחו היה שומע\u0004 אדם את \u0003קול השופר\u0004 שתוקעים בו במקדש כמה פעמים בכל יום. \u0003ויש אומרים\u0004 כי היו שומעים ביריחו \u0003אף\u0004 את \u0003קולו של\u0004 ה\u0003כהן\u0004 ה\u0003גדול בשעה שהוא מזכיר את השם\u0004 המפורש \u0003ביום הכפורים.\u0004","","ועוד, \u0003מיריחו היו מריחין\u0004 את \u0003ריח פיטום הקטורת\u0004 הבא מהמקדש. ובענין זה \u0003אמר ר' אלעזר בן דגלאי: עזים היו לאבא,\u0004 והיו רועות \u0003ב\u0004תחום \u0003ערי המכוור,\u0004 רחוק מירושלים, \u0003והיו מתעטשות מריח פיטום הקטורת\u0004 שהריחו. ושבים לסדר העבודה במקדש: \u0003מי שזכה ב\u0004שחיטת קרבן ה\u0003תמיד\u0004 — \u0003משכו\u0004 לכבש המיועד להקרבה כתמיד \u0003והולך\u0004 למקום שחיטתם של הקרבנות, שהוא \u0003בבית המטבחיים. ומי\u0004 מהכהנים \u0003שזכו ב\u0004העלאת ה\u0003אברים\u0004 לכבש היו \u0003הולכין עמו\u0004 אחריו. ומתארים את פרטי הדברים של \u0003בית המטבחיים\u0004 — עומד \u0003היה לצפונו של מזבח,\u0004 \u0003ועליו,\u0004 במקום בית המטבחיים, היו \u0003שמונה עמודים\u0004 של אבן \u0003ננסים\u0004 (נמוכים) \u0003ורבעים\u0004 (חתיכות עץ מרובעות) \u0003של ארז\u0004 היו קבועים \u0003על גביהן\u0004 של עמודים אלה. \u0003ואנקלאות\u0004 (ווים) \u0003של ברזל היו קבועין בהן,\u0004 בחתיכות העץ הרבועות. \u0003ושלשה סדרים\u0004 של ווי ברזל אלה היו \u0003לכל אחד ואחד\u0004 מחתיכות העץ הללו. \u0003שבהן\u0004 היו \u0003תולין\u0004 את הקרבן לאחר שנשחט, ומשם היו נוטלים אותו \u0003ומפשיטין\u0004 את עורו \u0003על שולחנות של שיש ש\u0004היו עומדים \u0003בין העמודים.\u0004","\u0003מי שזכה\u0004 בפייס \u0003בדישון מזבח הפנימי נכנס\u0004 דרך השער להיכל, \u0003ונטל את הטני\u0004 אותו הביא, \u0003והניחו\u0004 על רצפת ההיכל \u0003לפניו,\u0004 בינו לבין המזבח, \u0003והיה חופן\u0004 (לוקח מלוא חפניו) מן האפר שעל גבי המזבח, \u0003ונותן\u0004 אותו \u0003לתוכו\u0004 של הטני. \u0003ובאחרונה\u0004 (ולבסוף), כאשר לא נותר על המזבח אלא מעט דשן, \u0003כיבד\u0004 (טאטא) \u0003את השאר לתוכו\u0004 של הטני, \u0003והניחו\u0004 את הטני במקומו זה על רצפת ההיכל, \u0003ויצא\u0004 אל מחוץ להיכל. \u0003מי שזכה\u0004 בפייס \u0003בדישון המנורה\u0004 — \u0003נכנס\u0004 פנימה להיכל, \u0003ו\u0004אם \u0003מצא\u0004 במנורה את \u0003שני\u0004 ה\u0003נרות מזרחית\u0004 שבצד \u0003מערבית\u0004 (ראה גרסות) כשהם עדיין \u0003דולקין\u0004 — היה בתחילה \u0003מדשן\u0004 (מסיר את האפר והפתילות החרוכות ושם את הדשן שהסיר בתוך הכוז, ואחר כך שם בהם פתילות ושמן חדשים) \u0003את השאר\u0004 (חמשת הנרות האחרים), \u0003ו\u0004היה \u0003מניח\u0004 (משאיר) את אלו שני הנרות המזרחיים כשהם \u0003דולקין במקומן.\u0004 ואם כשנכנס להיכל \u0003מצאן\u0004 לשני הנרות המזרחיים \u0003שכבו\u0004 — היה \u0003מדשנן\u0004 (מסיר את הפחם שבראשי הפתילות ומכין אותן להדלקה) \u0003ומדליקן מן ה\u0004נרות האחרים שעדיין \u0003דולקין\u0004 (אם יש כאלה. ואם לאו, הריהו מדליקם מאש מזבח העולה). \u0003ואחר כך\u0004 היה \u0003מדשן את השאר\u0004 (שאר הנרות).","","","\u0003ואבן היתה לפני המנורה, ובה שלש מעלות\u0004 (מדרגות), \u0003שעליה\u0004 היה ה\u0003כהן עומד ומטיב את הנרות,\u0004 כי גובהה של המנורה היה שמונה עשר טפחים, ונצרך הכהן המטיב את הנרות לעמוד על מקום מוגבה כדי שיגיע אל הנרות. \u0003ו\u0004לאחר שדישן את חמש הנרות המערביים ושם את הפתילות החרוכות והאפר בתוך הכוז היה \u0003מניח את הכוז על\u0004 ה\u0003מעלה\u0004 ה\u0003שניה\u0004 שבאותה אבן, \u0003ויצא\u0004 מההיכל. ולאחר מכן, כשחזר להיטיב את שני הנרות המזרחיים והטיבם כאת חמשת הראשונים, היה מוציא את הכוז שבו דישון המנורה (יחד עם הכהן המוציא את הטני שבו דשן המזבח הפנימי), ושפכו את הדשן שבכוז (וכן שבטני) בצד המזבח.","","\u0003לא היו כופתין את הטלה\u0004 העומד להקרבה, בקשירת ארבע רגלים אלו לאלו, \u0003אלא\u0004 היו \u0003מעקידין אותו,\u0004 בקשירת רגל קדמית ואחורית זו לזו. \u0003מי\u0004 מהכהנים \u0003שזכו\u0004 בפייס \u0003ב\u0004העלאת ה\u0003אברים\u0004 לכבש היו \u0003אוחזין בו\u0004 בכבש בשעה שהיה נשחט. \u0003וכך היה עקידתו\u0004 של הקרבן, בשעה שהוא נשחט: עומד היה הקרבן בצפון העזרה ו\u0003ראשו\u0004 נמצא \u0003ל\u0004צד \u0003דרום,\u0004 כנגד מזבח, \u0003ופניו\u0004 מופנות \u0003ל\u0004צד \u0003מערב,\u0004 כנגד ההיכל. \u0003והשוחט עומד ב\u0004אופן שגופו פונה ל\u0003מזרח ופניו\u0004 פונות \u0003למערב.\u0004","שני קרבנות תמיד הם, של שחר ושל בין הערביים, אלא שזה \u0003של שחר היה נשחט על\u0004 יד \u0003קרן\u0004 (הפינה) ה\u0003צפונית מערבית\u0004 של המזבח, \u0003על\u0004 ה\u0003טבעת\u0004 ה\u0003שניה\u0004 מעשרים וארבע הטבעות (ששימשו להכנסת צוואר הבהמה הנשחטת) שהיו ברצפת העזרה בצפונו של המזבח. ואילו קרבן תמיד \u0003של בין הערבים היה נשחט על\u0004 יד \u0003קרן מזרחית צפונית\u0004 של המזבח, ו\u0003על\u0004 ה\u0003טבעת\u0004 ה\u0003שנייה.\u0004","ולאחר ש\u0003שחט השוחט\u0004 את הקרבן, \u0003וקבל המקבל\u0004 את הדם על מנת לזורקו על גבי המזבח, \u0003בא לו לקרן\u0004 ה\u0003מזרחית צפונית\u0004 של המזבח, \u0003ו\u0004היה \u0003נותן\u0004 (זורק) מהדם זריקה (\"נתינה\") ראשונה, ובאופן שיגיע הדם \u0003מזרחה\u0004 של המזבח ו\u0003צפונה\u0004 של המזבח. ולאחר מכן היה מגיע אל הקרן ה\u0003מערבית דרומית\u0004 של המזבח, \u0003ו\u0004היה \u0003נותן\u0004 נתינה שניה של דם, באופן שהדם יגיע \u0003מערבה\u0004 של המזבח ו\u0003דרומה\u0004 של המזבח. ואת \u0003שירי\u0004 (שאריות) \u0003הדם\u0004 שלא נזרק על המזבח, \u0003היה שופך אל יסוד דרומית\u0004 בקרן דרומית מערבית של היסוד."],["וכשהוא מפשיט את עורו של קרבן התמיד, לאחר שנשחט, \u0003לא היה שובר בו\u0004 בקרבן \u0003את הרגל\u0004 כמנהג הרווח אצל פושטי עורות, \u0003אלא\u0004 הריהו \u0003נוקבו מתוך ערקובו\u0004 (ברכו), בשתי ברכיו האחוריות, \u0003ו\u0004בנקבים אלה הריהו \u0003תולה בו\u0004 את הבהמה ברגליה על שני ווים, על מנת לפשוט את עורה.","וכך \u0003היה\u0004 אופן הפשטת העור: \u0003מפשיט\u0004 את עור הבהמה מלמעלה למטה, מתחיל בהפשטת עור רגליה, וממשיך \u0003ויורד עד ש\u0004הוא \u0003מגיע ל\u0004עור ה\u0003חזה.\u0004 כיון ש\u0003הגיע לחזה,\u0004 הפסיק את ההפשטה, ו\u0003חתך את הראש\u0004 (עם עורו של הראש, שאין עור הראש נפשט) \u0003ונתנו למי שזכה בו,\u0004 על מנת שיעלהו לכבש המזבח. ולאחר מכן \u0003חתך את\u0004 ארבע \u0003הכרעים\u0004 (חלק הרגל שעד הברכיים) \u0003ונתנן למי שזכה בהן\u0004 להעלות אף אותן. ולאחר מכן \u0003מרק\u0004 (סיים) \u0003את ההפשט\u0004 של שאר עור גוף הקרבן, מהחזה והלאה. \u0003קרע את הלב והוציא את דמו.\u0004","\u0003חתך את הידים\u0004 (שתי הרגליים הקדמיות) \u0003ונתנן למי שזכה בהן\u0004 להעלות אותן. ולאחר מכן \u0003עלה\u0004 בסכין אל חלקו האחורי של גוף הבהמה הנתון למעלה, \u0003לרגל הימנית, חתכה, ונתנה למי שזכה בה\u0004 להעלות אותה, \u0003ו\u0004נחתכת הרגל באופן שיהיו \u0003שתי\u0004 ה\u0003ביצים\u0004 של הקרבן (שהוא זכר) \u0003עמה,\u0004 ומעתה תלוי הקרבן ברגלו השמאלית. ולאחר מכן \u0003קרעו\u0004 לבטנו של הקרבן, \u0003ונמצא כולו\u0004 (כל קרביו) \u0003גלוי לפניו.\u0004","וכך היה נוהג באיברים הפנימיים: בתחילה \u0003נטל את הפדר\u0004 (חלב) \u0003ונתנו על בית שחיטת הראש מלמעלה,\u0004 מעל מקום השחיטה באופן שיסתיר את דם השחיטה שבראש, כשיעלה אותו הכהן לכבש. ולאחר מכן \u0003נטל את הקרביים, ונתנן למי שזכה בהן\u0004 להעלותם לכבש, ותחילה נוטלן על מנת \u0003להדיחן\u0004 (לשוטפם מפסולת ולכלוכים שבהם). \u0003ו\u0004את \u0003הכרס\u0004 שהפסולת המצויה בה רבה היו \u0003מדיחין אותה ב\u0004מקום הנקרא על שם כך \u0003\"בית המדיחין\",\u0004 המצוי בדרום העזרה, מצד מזרח לשער המים. \u0003ו\u0004היו \u0003מדיחין אותה כל צרכה\u0004 (עד שלא ישאר בה כל דבר מאוס) \u0003והקרביים מדיחין אותן שלש פעמים במעוטן\u0004 (לכל הפחות), ומכאן והלאה ניתן להוסיף עוד ועוד במספר ההדחות, כמידת הצורך, והיתה ההדחה נעשית בבית המטבחיים \u0003על שולחנות של שיש ש\u0004היו מצויים שם \u0003בין העמודים.\u0004","ולאחר מכן \u0003נטל את הסכין, ו\u0004חתך במקום החיבור בין הריאה והכבד, עד ש\u0003הפריש\u0004 (הפריד) \u0003את הריאה מן הכבד,\u0004 והותירה מחוברת לצואר \u0003ו\u0004כן הפריד בסכין שבידו את \u0003אצבע הכבד\u0004 חתיכת כבד היוצאת מקצהו התחתון של הכבד ונראית כאצבע, ונקראת גם יותרת הכבד) \u0003מן הכבד,\u0004 והותירה מחוברת לעוקץ (הזנב), \u0003ו\u0004לאחר שהפריד את הריאה מהכבד ואת אצבע הכבד מהכבד היה הכבד נותר מחובר לדופן הימנית, ו\u0003לא היה מזיזה,\u0004 ומשאיר את האיברים במקומם, שהריאה דבוקה לגרה (לצואר), והכבד דבוק לדופן, ואצבע הכבד דבוקה בזנב (בעוקץ), עד חיתוכם. ולאחר מכן הריהו \u0003נוקב את החזה\u0004 (חותך את סביבות החזה ומפרידו מהדפנות ומן הצלעות), \u0003ונתנה למי שזכה בה.\u0004","ולאחר מכן \u0003עלה\u0004 בסכין \u0003לדופן הימנית,\u0004 ו\u0003היה חותך\u0004 את הדופן ומפרידה מגוף הבהמה, מלמעלה למטה, כשהוא הולך \u0003ויורד עד השדרה,\u0004 כלומר, בסמוך לשדרה \u0003ו\u0004אולם \u0003לא היה נוגע בשדרה\u0004 והיא נשארת בשלמותה כשהיא דבוקה בדופן השמאלית, וכך הוא חותך \u0003עד ש\u0004הוא \u0003מגיע לבין שתי\u0004 ה\u0003צלעות\u0004 ה\u0003דקות\u0004 שבצד הצואר, ואותן לא חתך, השאירן במקומן. \u0003חתכה\u0004 (הפריד מן הגוף) את הדופן הימנית \u0003ונתנה למי שזכה בה, והכבד תלויה בה.\u0004","לאחר מכן \u0003בא לו לגרה\u0004 (צואר), ו\u0003הניח בה\u0004 בשלמותן, בלא לחותכן את \u0003שתי\u0004 ה\u0003צלעות\u0004 ש\u0003מכאן\u0004 (בצד הדופן הימנית), הן הצלעות שהניחן כאשר חתך את הדופן הימנית, \u0003ו\u0004כן הניח עוד \u0003שתי צלעות מכאן\u0004 (בצד הדופן השמאלית). \u0003חתכה\u0004 את הגרה, ונתנה למי שזכה בה, ו\u0003הקנה והלב והריאה תלוים בה.\u0004","ועתה \u0003בא לו ל\u0004חיתוכה של ה\u0003דופן השמאלית,\u0004 ו\u0003הניח בה\u0004 מלחתוך את \u0003שתי\u0004 ה\u0003צלעות\u0004 ה\u0003דקות\u0004 ש\u0003מלמעלן\u0004 (שבצד הזנב, שהרי הבהמה תלויה באופן שחלקה האחורי מונח למעלה), \u0003ו\u0004כן הניח את \u0003שתי\u0004 ה\u0003צלעות\u0004 ה\u0003דקות\u0004 ש\u0003מלמטן\u0004 (שבצד הצואר, כנזכר מקודם), \u0003וכך היה\u0004 גם \u0003מניח בחבירתה\u0004 (בדופן הימנית) את שתי הצלעות שבצד הצואר ובצד הזנב. \u0003נמצא\u0004 איפוא שהוא \u0003מניח שתים שתים\u0004 צלעות \u0003מלמעלן,\u0004 ו\u0003שתים שתים\u0004 צלעות \u0003מלמטן.\u0004","\u0003חתכה\u0004 את הדופן השמאלית \u0003ונתנה למי שזכה בה, והשדרה עמה, ו\u0004כן \u0003הטחול תלוי בה, ו\u0004הרי \u0003היא\u0004 הדופן השמאלית \u0003היתה גדולה,\u0004 שכן השדרה היתה אתה, \u0003אלא\u0004 שבכל זאת לדופן \u0003של ימין קורין \"גדולה\"\u0004 — וטעם הדבר: משום \u0003שהכבד תלויה בה.\u0004 לאחר מכן \u0003בא לו לעוקץ\u0004 (לזנב) הקרבן, \u0003חתכו, ונתנו למי שזכה בו,\u0004 ו\u0003האליה, ואצבע הכבד, ושתי\u0004 ה\u0003כליות עמו.\u0004 לאחר מכן \u0003נטל את הרגל השמאלית, חתכה, ונתנה למי שזכה בה.\u0004 ועתה, לאחר שנותח הקרבן ונמסר כל חלק שבו לכהן שזכה בהעלאתו לכבש המזבח, נמצאו כל תשעת הכהנים שזכו להעלות את איברי הקרבן לכבש המזבח \u0003כולן עומדים בשורה, והאברים\u0004 העומדים להעלאה נתונים \u0003בידם.\u0004"],["הכהן \u0003הראשון\u0004 מבין תשעת הכהנים שזכו בפייס בהעלאת האיברים לכבש המזבח — מחזיק בידו \u0003בראש\u0004 של הקרבן \u0003וברגל\u0004 האחורית הימנית של הקרבן, כאשר \u0003הראש\u0004 החשוב מן הרגל הוא \u0003ב\u0004יד \u0003ימינו. ו\u0004מחזיק את הראש באופן ש\u0003חוטמו\u0004 של הקרבן מופנה פנימה \u0003כלפי זרועו,\u0004 ואת \u0003קרניו\u0004 הוא מחזיק \u0003בין אצבעותיו,\u0004 ו\u0003בית\u0004 (מקום) \u0003שחיטתו\u0004 הוא \u0003מלמעלן, והפדר\u0004 (החלב) נתון עליה, לכיסוי מקום השחיטה. ואת \u0003הרגל של ימין\u0004 הוא מחזיק \u0003ב\u0004יד \u0003שמאלו, ובית עורן\u0004 (החלק החיצוני של הרגל, ממנו מופשט העור) פונה \u0003לחוץ.\u0004 הכהן \u0003השני\u0004 מתשעה הכהנים הזוכים בפייס — מחזיק \u0003בשתי\u0004 ה\u0003ידים\u0004 (רגליים קדמיות) של הקרבן, כאשר את הרגל \u0003של\u0004 צד \u0003ימין\u0004 הוא מחזיק \u0003ב\u0004יד \u0003ימינו, ו\u0004את הרגל \u0003של\u0004 צד \u0003שמאל\u0004 הוא מחזיק \u0003ב\u0004יד \u0003שמאלו, ו\u0004באופן ש\u0003בית עורן\u0004 פונה \u0003לחוץ.\u0004","הכהן \u0003השלישי\u0004 — מחזיק \u0003בעוקץ וברגל,\u0004 כאשר את \u0003העוקץ\u0004 הוא מחזיק \u0003ב\u0004יד \u0003ימינו, והאליה\u0004 המחוברת בו \u0003מדולדלת\u0004 (משתלשלת כלפי מטה) \u0003בין אצבעותיו, ואצבע הכבד ושתי כליות עמו,\u0004 עם העוקץ, נישאים כולם ביד ימינו של הכהן השלישי, ואילו את \u0003הרגל של\u0004 צד \u0003שמאל\u0004 הוא מחזיק \u0003ב\u0004יד \u0003שמאלו, ובית עורן\u0004 פונה \u0003לחוץ.\u0004 הכהן \u0003הרביעי\u0004 — מחזיק \u0003בחזה ובגרה\u0004 (= צוואר) כאשר את \u0003החזה\u0004 הוא מחזיק \u0003ב\u0004יד \u0003ימינו ו\u0004את \u0003הגרה\u0004 הוא מחזיק \u0003ב\u0004יד \u0003שמאלו, וצלעותיו\u0004 של הקרבן המונחות עם הגרה נתונות \u0003בין שני אצבעותיו.\u0004 הכהן \u0003החמישי\u0004 — מחזיק \u0003בשתי\u0004 ה\u0003דפנות,\u0004 כאשר הדופן \u0003של\u0004 צד \u0003ימין\u0004 נתונה \u0003ב\u0004יד \u0003ימינו, ו\u0004הדופן \u0003של\u0004 צד \u0003שמאל\u0004 נתונה \u0003ב\u0004יד \u0003שמאלו, ובית עורן לחוץ.\u0004 הכהן \u0003הששי\u0004 — מחזיק \u0003בקרבים הנתונים בבזך\u0004 (כעין קערה גדולה) \u0003ו\u0004ה\u0003כרעים\u0004 (החלקים התחתונים של הרגליים) נתונות \u0003על גביהן מלמעלה.\u0004","הכהן \u0003השביעי\u0004 — מחזיק \u0003בסולת\u0004 של המנחה הבאה עם התמיד. הכהן \u0003השמיני\u0004 — מחזיק \u0003בחביתים\u0004 (מנחת מחבת של הכהן הגדול הקרבה בכל יום, מחציתה האחת בבוקר ומחציתה השנית בערב). הכהן \u0003התשיעי\u0004 — מחזיק \u0003ביין\u0004 לנסך התמיד. ומשם נפנו ו\u0003הלכו\u0004 תשעת הכהנים עם הקרבנות שבידיהם \u0003ונתנום\u0004 על הכבש שהוא \u0003מחצי\u0004 \u0003הכבש ולמטה,\u0004 כלומר, בשש עשרה האמות התחתונות שלו (שאורך כולו שלשים ושתים אמה), \u0003ב\u0004צד \u0003מערבו. ומלחום\u0004 את איברי הקרבנות והמנחות \u0003וירדו ובאו להן ללשכת הגזית\u0004 כדי \u0003לקרות את\u0004 קריאת \u0003שמע\u0004 של שחרית ושאר דברים הנאמרים על ידם (כאשר יבואר בתחילת הפרק הבא).","א גמרא שנינו במשנתנו כי את טלה קרבן התמיד היו מעקידים, ובענין זה עוד \u0003תנא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 עקידתו של הקרבן היתה בקשירת \u0003יד ורגל, כ\u0004דרך \u0003עקידת יצחק בן אברהם\u0004 בהר המוריה.","שנינו בתחילת משנתנו כי \u0003לא היו כופתין את הטלה,\u0004 ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ונמסר כי נחלקו בכך \u0003רב הונא ורב חסדא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אין כופתים את הטלה \u0003משום בזיון קדשים\u0004 שיש בדבר. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אין כופתים את הטלה \u0003משום\u0004 שכך נוהגים הגויים, והעושה כן הריהו \u0003מהלך בחוקי העמים\u0004 שאסרה התורה (\"ובחוקותיהם לא תלכו\", ויקרא יח, ג).","ודנים, \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל להלכה יש \u0005ביניהן]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל להלכה \u0005ביניהן]\u0006 במקרה \u0003דכפתיה בשיראי\u0004 \u0005[שכפתו\u0006 את הקרבן \u0005בשיראין,\u0006 בבגד משי\u0005],\u0006 שלדעה שהוא משום בזיון קדשים — באופן זה, כשהכפיתה נעשית בבגד כה יקר, אין בכך משום בזיון קדשים. ואילו לדעה כי הוא משום הליכה בחוקות הגויים — אף באופן זה יש משום הליכה בחוקות הגויים. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 באופן הבא יש ביניהן אותו הבדל להלכה — כאשר כופתים את הקרבן \u0003(בהוצא) [בחוטא] דדהבא\u0004 \u0005[בחוט של זהב],\u0006 שמשום בזיון קדשים אין בדבר, ואולם משום הליכה בחוקות הגויים יש בו.","שנינו במשנתנו כי את הקרביים היו מדיחים על שולחנות של שיש שהיו בבית המטבחיים שבמקדש, ובענין השולחנות שבמקדש \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במסכת שקלים\u0005]:\u0006 \u0003שלש עשרה שולחנות היו במקדש.\u0004 ואלו הם: \u0003שמונה\u0004 שולחנות \u0003של שיש\u0004 היו נתונים \u0003בבית המטבחיים\u0004 שבצפון המזבח, בין הטבעות והעמודים, \u0003שעליהם מדיחין את הקרבים\u0004 של הקרבנות.","עוד \u0003שני\u0004 שולחנות היו נתונים \u0003ב\u0004צד \u0003מערבה של\u0004 ה\u0003כבש\u0004 בדרומו של המזבח, \u0003אחד\u0004 מהם היה \u0003של שיש ואחד\u0004 מהם היה \u0003של כסף. על\u0004 השולחן \u0003של שיש\u0004 היו \u0003נותנין את האברים\u0004 העומדים להקרבה, ומשם היו מעלים אותם למזבח. \u0003ועל\u0004 השולחן \u0003של כסף\u0004 היו נותנים את תשעים ושלשה \u0003כלי\u0004 ה\u0003שרת\u0004 אותם היו מוציאים בתחילת כל יום מלשכת הכלים.","\u0003ובאולם\u0004 העומד לפני ההיכל היו עוד \u0003שנים\u0004 שולחנות \u0003מבפנים\u0004 האולם \u0003על\u0004 (אצל) \u0003פתח הבית, אחד\u0004 מהם היה \u0003של כסף ואחד\u0004 מהם היה \u0003של זהב. על\u0004 השולחן \u0003של כסף\u0004 היו \u0003נותנין\u0004 את \u0003לחם הפנים בכניסתו\u0004 לאחר שנאפה בערב שבת, עד שמניחים אותו במקומו. \u0003ועל\u0004 השולחן \u0003של זהב\u0004 היו מניחים את לחם הפנים הישן \u0003ביציאתו\u0004 מההיכל, ומשולחן זה היה הלחם מתחלק לכהנים. וטעם הדבר שהשולחן המשמש את לחם הפנים ביציאתו הוא של זהב ולא של כסף?","\u0003ש\u0004כן כלל הוא: \u0003מעלין ב\u0004דברי \u0003קודש ולא מורידין\u0004 בהם, ואף לחם הפנים המוצא, לאחר שעלה במדרגתו והיה כבר מונח על שולחן זהב (שולחן לחם הפנים), אין זה ראוי שירד ממדרגתו ויונח על שולחן שאינו של זהב. \u0003ו\u0004עוד שולחן \u0003אחד של זהב\u0004 היה \u0003בפנים,\u0004 הוא השולחן \u0003שעליו\u0004 מונח \u0003לחם הפנים תמיד\u0004 (ככתוב: \"ועשית שולחן עצי שטים... וצפית אותו זהב טהור... ונתת על השולחן לחם פנים לפני תמיד\", שמות כה, כג-ל).","ושואלים: \u0003מכדי\u0004 \u0005[והלא]\u0006 כלל הוא ש\u0003אין\u0004 מקום להנהגות של \u0003עניות במקום\u0004 של \u0003עשירות,\u0004 ומשום כך במקדש שנוהגים בדרך עשירות, יש לשאול \u0003אמאי עבדי\u0004 \u0005[מדוע עשו]\u0006 שולחנות של \u0003שיש? ניעבדו\u0004 \u0005[שיעשו]\u0006 שולחנות של \u0003כסף, ניעבדו\u0004 \u0005[שיעשו]\u0006 שולחנות של \u0003זהב! אמר רב חיננא בשם ר' אסי, ור' אסי\u0004 אמר הסבר זה \u0003בשם ר' שמואל בר רב יצחק: מפני שהוא,\u0004 שולחן של מתכת, המתחמם מחמת השמש, חוזר ו\u0003מרתיח\u0004 (מחמם) את הדבר המונח עליו, ועלול הדבר לגרום לקלקולם של הקודשים.","שנינו במשנתנו כי קרבן התמיד \u0003של שחר היה נשחט על\u0004 יד ה\u0003קרן מזרחית צפונית\u0004 של המזבח, על הטבעת הראשונה שבשורה השניה שבסדר השורות מדרום לצפון (המכונה במשנתנו \"טבעת שניה\"), ואילו התמיד של בין הערביים היה נשחט על הטבעת הרביעית של השורה השניה (ואף זו מכונה במשנתנו \"טבעת שניה\"). ודנים: \u0003מנא הני מילי\u0004 \u0005[מנין אלה הדברים,\u0006 מה מקורם בתורה\u0005]? אמר רב חסדא:\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדינו של קרבן התמיד \"...תקריבו לה' כבשים בני שנה תמימים \u0003שנים ליום\u0004 עולה תמיד\" (במדבר כח, ג), ומהמלה \"ליום\" למדים שהשחיטה צריכה להיות \u0003כנגד\u0004 אור \u0003היום,\u0004 היא השמש, שיגיע אור השמש למקום שחיטת התמיד, ומשום כך, אין הם נשחטים על הטבעת שבשורה הראשונה, שבגלל גובהו של המזבח, אין אור השמש מגיע אליה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 ברייתא \u0005גם כן\u0006 האומרת \u0005כך]:\u0006 \u0003\"שנים ליום\"\u0004 — שתהא שחיטתו \u0003כנגד היום.\u0004 ודנים: \u0003אתה אומר\u0004 בפירוש הדברים שהוא \u0003נגד היום, או אינו אלא\u0004 פירושו בפשטות \u0003חובת היום\u0004 — \u0003כשהוא,\u0004 הכתוב, \u0003אומר\u0004 בפסוק שלאחריו \u0003\"את הכבש אחד תעשה בבקר ואת הכבש השני תעשה בין הערבים\"\u0004 — \u0003הרי חובת היום אמור, הא\u0004 \u0005[הרי]\u0006 מעתה ב\u0003מה אני מקיים\u0004 את הכתוב \u0003\"שנים ליום\"?\u0004 — שתהא שחיטתו \u0003נגד היום.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 כיצד נעשה הדבר בשני התמידים? קרבן \u0003תמיד של שחר\u0004 הנשחט בבוקר, כאשר השמש במזרח — \u0003היה נשחט על\u0004 יד ה\u0003קרן צפונית מערבית\u0004 של המזבח מול השמש, \u0003על\u0004 ה\u0003טבעת\u0004 ה\u0003שניה, ו\u0004קרבן התמיד \u0003של בין הערבים\u0004 הנשחט כאשר השמש נמצאת במערב — \u0003היה נשחט על\u0004 יד ה\u0003קרן צפונית מזרחית על\u0004 ה\u0003טבעת\u0004 ה\u0003שניה.\u0004","ומתוך שדובר בענין מהלך השמש בשמים, מספרים: \u0003עשרה דברים שאל אלכסנדרוס מוקדון את זקני הנגב\u0004 (הדרום), \u0003אמר להן:\u0004"],["האם \u0003מן השמים לארץ רחוק\u0004 יותר מהמרחק מן המזרח למערב, \u0003או\u0004 המרחק \u0003מ\u0004ה\u0003מזרח למערב\u0004 גדול יותר מהמרחק שבין השמים והארץ? \u0003אמרו לו\u0004 זקני הנגב: המרחק \u0003ממזרח למערב\u0004 גדול יותר. \u0003תדע\u0004 לך, ראיה לדבר, \u0003שהרי\u0004 כאשר ה\u0003חמה\u0004 מצויה \u0003במזרח\u0004 בתחילת היום — \u0003הכל מסתכלין\u0004 (יכולים להסתכל) \u0003בה,\u0004 בלא שתיפגענה עיניהם, וכן הוא כאשר ה\u0003חמה\u0004 מצויה \u0003במערב\u0004 בסוף היום — \u0003הכל מסתכלין בה,\u0004 ואולם בזמן שה\u0003חמה\u0004 נמצאת \u0003באמצע\u0004 ה\u0003רקיע\u0004 בחצות היום — \u0003אין הכל מסתכלין בה,\u0004 שכל המסתכל בה נפגעות עיניו, וטעם הדבר — שקרוב יותר הוא מקום זה.","\u0003ו\u0004אילו \u0003חכמים אומרים: זה וזה כאחד שוין,\u0004 וראיה לדבר מן הכתוב, \u0003ש\u0004כן \u0003נאמר\u0004 \"כי \u0003כגבוה שמים על הארץ\u0004 גבר חסדו על יראיו. \u0003כרחוק מזרח ממערב\u0004 הרחיק ממנו את פשעינו\" (תהלים קג, יא-יב), שכתוב אחד משווה את מידת החסד כמרחק השמים לארץ, וכתוב אחד משווה את מידת הסליחה כמרחק המזרח ממערב. \u0003ואי חד מינייהו נפיש\u0004 \u0005[ואם אחד מהם,\u0006 מהמרחקים הללו \u0005גדול\u0006 יותר מחבירו\u0005],\u0006 נכתוב תרווייהו כי ההוא דנפיש \u0005[שיכתוב\u0006 את \u0005שניהם,\u0006 בשני הכתובים הללו, גם בתיאור מידת החסד וגם בענין הסליחה, שהם \u0005כמו אותו\u0006 המרחק \u0005שגדול\u0006 יותר]! \u0003ואלא\u0004 באשר לשאלה, מדוע ניתן לראות את השמש כאשר היא נמצאת במזרח ובמערב, בעוד שכאשר ה\u0003חמה\u0004 נמצאת \u0003באמצע\u0004 ה\u0003רקיע מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אין הכל\u0004 יכולים להיות \u0003מסתכלין בה?\u0004 — \u0003משום דקאי להדיא, ולא כסי ליה מידי\u0004 \u0005[שעומדת\u0006 החמה ב\u0005גילויה, באין דבר המכסה אותה],\u0006 בעוד שבהיותה במזרח או במערב ישנם דברים המסתירים את קרניה הישירות.","ועוד \u0003אמר להן\u0004 אלכסנדר מוקדון לזקני הנגב בשאלה שעניינה סדר הבריאה בראשיתה: האם \u0003שמים נבראו תחלה\u0004 ולאחריהם הארץ \u0003או הארץ\u0004 נבראה תחילה ולאחריה השמים? \u0003אמרו\u0004 לו בתשובה: \u0003שמים נבראו תחלה, ש\u0004כן \u0003נאמר\u0004 בתחילת התורה, בתחילת תיאור מעשה הבריאה ה\u0003\"בראשית ברא אלהים את השמים ואת הארץ\"\u0004 (בראשית א, א).","\u0003אמר להן\u0004 אלכסנדר מוקדון עוד בשאלה: מה נברא בתחילה, האם ה\u0003אור נברא תחלה\u0004 ולאחריו החושך, \u0003או\u0004 ה\u0003חשך\u0004 נברא תחילה ולאחריו האור? \u0003אמרו לו\u0004 זקני הנגב בתשובה: \u0003מילתא דא\u0004 \u0005[דבר זה]\u0006 \u0003אין לה פתר\u0004 \u0005[פתרון]\u0006 מן הכתובים. \u0003ו\u0004שואלים: מדוע לא ענו לו על שאלה זו, והרי יש לה פתרון בכתובים, \u0003נימרו ליה\u0004 \u0005[שיאמרו לו]\u0006 כי ה\u0003חשך נברא תחלה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"והארץ היתה תהו ובהו וחשך\u0004 על פני תהום ורוח אלקים מרהפת על פני המים\" (שם ב), \u0003והדר\u0004 \u0005[וחזר,\u0006 ולאחר מכן\u0005]\u0006 נאמר \u0003\"ויאמר אלהים יהי אור ויהי אור\"!\u0004","ומשיבים: אכן יכלו זקני הנגב להשיבו כך, ואולם הם העדיפו שלא לענות לו על שאלתו זו, כי \u0003סברי\u0004 \u0005[סבורים היו]\u0006 שאם ישיבוהו על שאלה זו, \u0003דילמא אתי לשיולי\u0004 \u0005[שמא יבוא לשאול]\u0006 אותם שאלות נוספות במופלאות הבריאה, כגון \u0003מה למעלה ומה למטה, מה לפנים ומה לאחור,\u0004 והרי אלה שאלות שאסור לשאול אותן.","ומקשים על כך: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמחמת חשש זה לא השיבוהו על שאלתו בענין קדימת בריאת האור והחושך, אף על שאלתו בענין קדימת בריאת ה\u0003שמים\u0004 והארץ \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נימרו ליה\u0004 \u0005[לא יאמרו לו],\u0006 מחמת אותו חשש, שמא מתוך כך יבוא לשאול מה למעלה ומה למטה, מה לפנים ומה לאחור?! ומשיבים: \u0003מעיקרא סבור\u0004 \u0005[בתחילה,\u0006 כאשר שאלם בנושא קדימת בריאת השמים והארץ, \u0005סברו\u0006 זקני הנגב\u0005]\u0006 כי אין זה אלא \u0003אקראי בעלמא\u0004 \u0005[מקרה\u0006 מזדמן וחולף \u0005בלבד]\u0006 הוא זה ש\u0003הוא דקא שייל\u0004 \u0005[שהוא שואל]\u0006 אותם שאלה הנוגעת לקדימת הבריאה, ואולם \u0003כיון דחזו דקהדר שאיל\u0004 \u0005[שראו שהוא חוזר\u0006 ו\u0005שואל]\u0006 שאלה נוספת בנושא זה, \u0003סברי\u0004 \u0005[סברו]\u0006 כי מוטב ש\u0003לא נימא ליה\u0004 \u0005[נאמר לו\u0006 תשובה על שאלתו\u0005]\u0006 \u0003דילמא אתי לשיולי\u0004 \u0005[שמא יבוא לשאול]\u0006 \u0003מה למעלה מה למטה, מה לפנים ומה לאחור.\u0004","ולאחר מכן \u0003אמר להם\u0004 אלכסנדר מוקדון לזקני הנגב בשאלה שבענין האדם: \u0003אידין מתקרי חכים\u0004 \u0005[איזהו\u0006 האדם \u0005הנקרא,\u0006 הראוי באמת להיקרא \u0005חכם]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 כדברי המשנה: \u0003איזהו חכם?\u0004 — \u0003הרואה את הנולד. אמר להם\u0004 בשאלה בענין זה: \u0003אידין מתקרי\u0004 \u0005[איזהו\u0006 אדם \u0005הנקרא]\u0006 \u0003גבור? אמרו לו\u0004 בלשון המשנה: \u0003איזהו גבור?\u0004 — \u0003הכובש את יצרו. אמר להן\u0004 עוד: \u0003אידין מתקרי\u0004 \u0005[איזהו\u0006 אדם \u0005הנקרא]\u0006 \u0003עשיר?\u0004 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 באותו אופן: \u0003איזהו עשיר?\u0004 — \u0003השמח בחלקו.\u0004","\u0003אמר להן: מה יעביד איניש\u0004 \u0005[יעשה אדם]\u0006 \u0003ויחיה? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ימית עצמו.\u0004 כלומר, יצמצם צרכיו ויקטין עצמו. ועוד שאל: \u0003מה יעביד איניש\u0004 \u0005[יעשה אדם]\u0006 \u0003וימות?\u0004 השיבו לו: \u0003יחיה את עצמו.\u0004 כלומר, ינהג בגדולה וברווחה רבה. \u0003אמר להן: מה יעביד איניש\u0004 \u0005[יעשה אדם]\u0006 \u0003ויתקבל על ברייתא\u0004 \u0005[הבריות]?\u0006 \u0003אמרו\u0004 לו: \u0003יסני מלכו ושלטן\u0004 \u0005[ישנא\u0006 את \u0005המלכות והשלטון].\u0006 ולא ימצא בקרבתם, אלא בתוך עמו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דידי טבא מדידכו\u0004 \u0005[\u0006עצתי \u0005שלי טובה\u0006 יותר \u0005מ\u0006העצה \u0005שלכם],\u0006 שאני אומר כי הדרך להתקבל על הבריות היא ש\u0003ירחם מלכו ושלטן, ויעבד טיבו עם בני אינשא\u0004 \u0005[שיאהב\u0006 את \u0005המלך והשלטון,\u0006 ויתקרב אליהם, \u0005ו\u0006על ידי כך יוכל \u0005לעשות טובות עם בני האדם].\u0006 הנזקקים לשלטון, ומתוך כך יהיה מקובל ואהוב על הבריות.","ועוד \u0003אמר להן\u0004 בשאלה: היכן עדיף לו לאדם לגור, האם \u0003בימא יאי למידר\u0004 \u0005[בים ראוי לדור]\u0006 \u0003או ביבשתא יאי למידר\u0004 \u0005[ביבשה ראוי לדור]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ביבשתא יאי למידר\u0004 \u0005[ביבשה ראוי לדור],\u0006 וראיה לדבר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כל נחותי ימא\u0004 \u0005[יורדי הים]\u0006 \u0003לא מיתבא דעתיהון\u0004 \u0005[מתיישבת דעתם]\u0006 עליהם \u0003עד דסלקין ליבשתא\u0004 \u0005[שעולים ליבשה].\u0006","ועוד \u0003אמר להן\u0004 אלכסנדר מוקדון לזקני הנגב: \u0003אידין מנכון חכים יתיר\u0004 \u0005[איזה מכם החכם יותר\u0006 מחבריו\u0005]?\u0006 \u0003אמרו לו: כולנא כחדא שוויין\u0004 \u0005[כולנו כאחד שווים\u0006 בחכמה\u0005],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כל מילתא\u0004 \u0005[דבר]\u0006 ש\u0003אמרת לנא\u0004 \u0005[לנו]\u0006 בשאלה — \u0003בחד פתרנא\u0004 \u0005[כאחד,\u0006 ביחד, \u0005פתרנו]\u0006 \u0003לך.\u0004 עוד \u0003אמר להן: מה דין אתריסתון לקבלי\u0004 \u0005[מה זה\u0006 ש\u0005אתם\u0006 היהודים, \u0005מתריסים כלפי,\u0006 מתנגדים לי\u0005],\u0006 והרי אנחנו הם הרבים, ואתם משועבדים תחתנו, והרי זה מורה שהצדק עמנו! \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 בתשובה: אין בדבר זה להורות כן, שהרי אף \u0003סטנא נצח\u0004 \u0005[השטן מנצח]\u0006 מטעה בני אדם וגובר עליהם אף שברור שאין הצדק עמו.","\u0003אמר להן: הא אנא מקטילנא יתכון\u0004 \u0005[הרי אני יכול להרוג אתכם]\u0006 \u0003בגזירת מלכין\u0004 \u0005[מלכים]!\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 אמנם \u0003שלטן\u0004 \u0005[השלטון]\u0006 נתון \u0003ביד מלכא\u0004 \u0005[המלך],\u0006 ובידך להמיתנו, \u0003ו\u0004אולם כיוון שהבטחנו שלא תפגע בנו, \u0003לא יאי למלכא כזב\u0004 \u0005[אין\u0006 זה \u0005נאה למלך השקר].\u0006 \u0003מיד\u0004 פקד אלכסנדר מוקדון \u0003אלביש יתהון לבושין דארגוון\u0004 \u0005[הלביש, אותם לבושי ארגמן,\u0006 לבושי שררה מפוארים\u0005],\u0006 \u0003ושדי מניכא דדהבא\u0004 \u0005[ושם רבדי זהב]\u0006 \u0003על צואריהון\u0004 \u0005[צוארם].\u0006","כיון שעמד להיפרד מהם, \u0003אמר להן: בעינא דאיזל\u0004 \u0005[רוצה אני ללכת]\u0006 \u0003למדינת אפריקי\u0004 להלחם בה, מה דעתכם בענין זה? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא מצית אזלת\u0004 \u0005[אינך יכול ללכת]\u0006 לשם משום \u0003דפסקי\u0004 \u0005[שפוסקים,\u0006 חוצצים\u0005] הרי חשך\u0006 בפני ההולכים לשם. \u0003אמר להן: לא סגיא דלא אזלינא\u0004 \u0005[אי אפשר שלא אלך],\u0006 לשם, ו\u0003אמטו הכי משיילנא לכו\u0004 \u0005[משום כך אני שואל אתכם]\u0006 בעצתכם, \u0003אלא מאי אעביד\u0004 \u0005[מה אעשה]\u0006 כדי לעבור אותם הרי חושך?","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אייתי חמרי לובאי דפרשי בהברא\u0004 \u0005[הבא,\u0006 קח אתך, \u0005חמורים לובים שמהלכים\u0006 אף \u0005בחושך],\u0006 והם יובילו אותך במעברים החשוכים ההם. \u0003ואייתי קיבורי דמתני\u0004 \u0005[והבא\u0006 אתך \u0005צרורות חבלים],\u0006 \u0003וקטר בהאי גיסא\u0004 \u0005[וקשור בצד זה]\u0006 של הרי החושך, כשאתה נכנס אל תוכם, את קצהו האחד של החבל, באופן זה \u0003דכי אתית (באורחא) נקטת בגוייהו\u0004 \u0005[שכאשר תבוא בדרך\u0006 חזרה \u0005אחוז בהם]\u0006 \u0003ו\u0004כך תוכל \u0003אתית לאתרך\u0004 \u0005[לבוא,\u0006 לשוב \u0005למקומך].\u0006","\u0003עבד הכי, ואזל מטא לההוא מחוזא דכוליה נשי\u0004 \u0005[עשה כך, והלך\u0006 ו\u0005הגיע\u0006 \u0005לאותו מחוז שכולו נשים].\u0006 \u0003בעי למיעבד קרבא בהדייהו\u0004 \u0005[רצה לעשות מלחמה אתן].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 אין זה כדאי לך להלחם בנו, שכן \u0003אי קטלת לן\u0004 \u0005[אם\u0006 תנצח במלחמה ו\u0005תהרוג אותנו]\u0006 — \u0003יאמרו\u0004 הבריות \u0003נשי קטל\u0004 \u0005[נשים הרג],\u0006 ואין בכך גבורה, ו\u0003אי קטילנא לך\u0004 \u0005[ואם\u0006 אנחנו ננצח ו\u0005נהרוג אנחנו אותך]\u0006 — \u0003יאמרו\u0004 הבריות עליך: הרי \u0003מלכא דקטלוהו נשי\u0004 \u0005[מלך שהרגוהו נשים\u0006 במלחמה\u0005].\u0006 \u0003אמר להן: אייתו\u0004 \u0005[הביאו]\u0006 \u0003לי נהמא\u0004 \u0005[לחם]!\u0006 \u0003אייתו ליה נהמא דדהבא, אפתורא דדהבא\u0004 \u0005[הביאו לו לחם זהב\u0006 מונח \u0005על\u0006 גבי \u0005שולחן של זהב].\u0006"],["\u0003אמר להו\u0004 \u0005[להם]\u0006 אלכסנדר מוקדון בתמיהה: \u0003מי אכלי אינשי נהמא דדהבא\u0004 \u0005[האם אוכלים אנשים לחם זהב]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני המקום: \u0003אלא אי נהמא בעית\u0004 \u0005[אם לחם\u0006 רגיל לאכילה הוא מה ש\u0003רצית]\u0004 בהליכתך לכאן, וכי \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003לך באתרך נהמא למיכל\u0004 \u0005[במקומך לחם לאכול],\u0006 \u0003דשקלית ואתית להכא\u0004 \u0005[שנטלת\u0006 עצמך \u0005ובאת לכאן]?\u0006 \u0003כי נפיק ואתי\u0004 \u0005[כאשר יצא ובא\u0006 ללכת לארצו\u0005],\u0006 \u0003כתב\u0004 אלכסנדר מוקדון \u0003אבבא מחוזא\u0004 \u0005[על שער העיר]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003אלכסנדרוס מוקדון, הויתי שטייא\u0004 \u0005[הייתי שוטה]\u0006 \u0003עד דאתיתי\u0004 \u0005[שבאתי]\u0006 \u0003למדינת אפריקי דנשיא\u0004 \u0005[של הנשים],\u0006 \u0003ויליפת\u0004 \u0005[ולמדתי]\u0006 \u0003עצה\u0004 תבונה, \u0003מן נשיא\u0004 \u0005[הנשים].\u0006","עוד מסופר: \u0003כי שקיל ואתי\u0004 \u0005[כאשר נטל ובא\u0006 לדרכו\u0005],\u0006 \u0003יתיב אההוא מעיינא\u0004 \u0005[ישב על\u0006 \u0005מעין אחד],\u0006 \u0003קא אכיל נהמא\u0004 \u0005[היה אוכל לחם],\u0006 \u0003הוו בידיה גולדני דמלחא\u0004 \u0005[היו בידיו דגים מלוחים],\u0006 \u0003בהדי דמחוורי להו\u0004 \u0005[בתוך שהלבינם,\u0006 רחץ אותם במים\u0005]\u0006 על מנת להסיר מהם את מלחם — \u0003נפל בהו ריחא\u0004 \u0005[בהם ריח]\u0006 טוב ביותר. \u0003אמר\u0004 אלכסנדר מוקדון לעצמו: \u0003שמע מינה\u0004 \u0005[למד ממנה,\u0006 מכאן\u0005]\u0006 כי \u0003האי עינא\u0004 \u0005[מעין זה]\u0006 \u0003מגן עדן אתי\u0004 \u0005[בא].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003שקל מהנהו מיא\u0004 \u0005[לקח מאותם מים]\u0006 ו\u0003טרא באפיה\u0004 \u0005[שטף\u0006 בהם את \u0005פניו].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי אלכסנדר מוקדון \u0003אידלי כוליה\u0004 \u0005[עלה\u0006 לכל אורך המעין \u0005כולו]\u0006 \u0003עד דמטא לפתחא\u0004 \u0005[שבא לפתח]\u0006 \u0003גן עדן\u0004 הנעול. עמד ו\u0003רמא קלא\u0004 \u0005[הרים קול]:\u0006 \u0003פתחו לי בבא\u0004 \u0005[שער]!\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 כלשון הכתוב \u0003\"זה השער לה'\u0004 צדיקים יבואו בו\" (תהלים קיח, כ), ואין אתה בכלל הצדיקים. \u0003אמר להון\u0004 \u0005[להם]:\u0006 \u0003אנא נמי מלכא אנא, מיחשב חשיבנא\u0004 \u0005[אני גם כן מלך אני, חשוב אני],\u0006 ואם איני נכנס פנימה, לפחות \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי מידי\u0004 \u0005[משהו]\u0006 מגן עדן. \u0003יהבו ליה גולגלתא חדא\u0004 \u0005[נתנו לו גולגולת אחת],\u0006 \u0003אתייה תקליה לכוליה דהבא וכספא דידיה בהדיה\u0004 \u0005[בא לשקול\u0006 את \u0005כל הכסף והזהב שלו אתה,\u0006 כנגדה\u0005],\u0006 \u0003ולא הוה מתקליה\u0004 \u0005[לא היתה\u0006 הגולגולת \u0005נשקלת,\u0006 לא היה ידוע משקלה האמיתי\u0005],\u0006 שהכריעה כל מה שכנגדה. \u0003אמר\u0004 אלכסנדר \u0003להון לרבנן\u0004 \u0005[להם לחכמים]:\u0006 \u0003מאי האי\u0004 \u0005[מה זאת],\u0006 מדוע אי אפשר למצוא משקל כנגדה? \u0003אמרי\u0004 \u0005[אמרו]\u0006 לו: \u0003גולגלתא דעינא דבישרא ודמא\u0004 \u0005[גולגולת עינו של בשר ודם]\u0006 היא, \u0003דלא קא שבע\u0004 \u0005[ש\u0006לעולם \u0005אין היא שבעה]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ממאי דהכי\u0004 \u0005[ממה,\u0006 מנין \u0005שכך]\u0006 \u0003הוא?\u0004 אמרו לו החכמים: \u0003שקלי קלילי עפרא, וכסייה\u0004 \u0005[קח מעט עפר, וכסהו]\u0006 את העין הזו, ועשה כן, ואכן \u0003לאלתר תקלא\u0004 \u0005[מיד נשקלה,\u0006 נמצא משקלה\u0005]\u0006 ששקלה כמשקלה האמיתי. ומנין שכל עוד היא רואה אינה שבעה? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"שאול ואבדון לא תשבענה\u0004 ועיני האדם לא תשבענה\" (משלי כז, כ).","","ומתוך שנזכרו הרי חושך בסיפורו של אלכסנדר מוקדון, מביאים עוד. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם של \u0005בית\u0006 המדרש\u0005] של\u0006 \u0003אליהו: גיהנם\u0004 הריהו מצוי \u0003למעלה מן הרקיע, ויש אומרים\u0004 כי הגיהנם מצוי \u0003לאחורי הרי חשך.\u0004 ומסיימים (את הפרק, ואת חלק התלמוד שבמסכת זו) בדברים שבשבח לומדי תורה. \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: כל העוסק בתורה בלילה\u0004 — \u0003שכינה כנגדו, ש\u0004כן \u0003נאמר: \"קומי רוני בלילה לראש אשמורות שפכי כמים לבך נכח פני ה' \"\u0004(איכה ב, יט). \u0003אמר ר' אלעזר בן עזריה: תלמידי חכמים מרבים שלום בעולם, ש\u0004כן \u0003נאמר: \"וכל בניך לימודי ה' ורב שלום בניך\"\u0004 (ישעיה נד, יג), הרי שתלמידי החכמים (\"בניך לימודי ה' \", ונדרשת המלה \"בניך\" במובן \"בוניך\", בוני עם ישראל) מרבים שלום (\"ורב שלום בניך\"). א משנה לאחר שהניחו הכהנים את אברי התמיד על כבש המזבח ומלחום הלכו ללשכת הגזית.","","","ומשבאו לשם \u0003אמר להם הממונה\u0004 על הפייסות: עמדו ו\u0003ברכו ברכה אחת\u0004 מברכות קריאת שמע! \u0003והם\u0004 עשו כן ו\u0003ברכו.\u0004 ולאחר מכן \u0003קראו\u0004 את \u0003עשרת הדברות,\u0004 ואת שלש פרשיותיה של קריאת שמע: \u0003\"שמע\", \"והיה אם שמוע\", \"ויאמר\",\u0004 ולאחר מכן","\u0003ברכו את העם\u0004 (ראה עיונים) \u0003שלש ברכות,\u0004 שהן: הברכה שלאחר אמירת קריאת שמע \u0003\"אמת ויציב\",\u0004 הנחתמת במלים \"גאל ישראל\", וברכת ה\u0003עבודה\u0004 במקדש (ברכת \"רצה\" שבסדר תפילת שמונה עשרה), \u0003וברכת כהנים\u0004 (ראה עיונים), \u0003וב\u0004יום ה\u0003שבת\u0004 בו מתחלפים משמרות הכהנים במקדש (שהמשמר היוצא מקריב עדיין את קרבן התמיד של שחר, והמשמר הנכנס מקריב את המוספים) היו אנשי המשמר היוצא \u0003מוסיפין ברכה אחת\u0004 \u0003ל\u0004אנשי ה\u0003משמר היוצא\u0004 שעיקרה שישררו האהבה והאחוה השלום והרעות ביניהם.","ולאחר שקראו הכהנים את עשרת הדברות וקריאת שמע וברכו את העם, \u0003אמר להם\u0004 הממונה: כהנים \u0003חדשים\u0004 (שמימיהם עדיין לא זכו) \u0003ל\u0004הקטיר את ה\u0003קטרת,\u0004 אלה בלבד \u0003בואו והפיסו\u0004 (השתתפו בגורל) מי הוא שיזכה להקטיר את קטורת היום. ולאחר הפייס, ש\u0003זכה\u0004 מבין הכהנים \u0003מי שזכה, אמר להם\u0004 הממונה לכל הכהנים: כולכם, הכהנים ה\u0003חדשים\u0004 (שמימיהם עדיין לא העלו אברי קרבנות למזבח עד כה) יחד \u0003עם\u0004 הכהנים ה\u0003ישנים\u0004 (ותיקים, שכבר עשו עבודה זו), \u0003בואו והפיסו מי\u0004 מכם הוא זה ש\u0003מעלה\u0004 את ה\u0003אברים מן הכבש למזבח\u0004 להקריבם ולנסך את נסכיהם! \u0003ר' אליעזר בן יעקב אומר:\u0004 לא היו עורכים פייס מיוחד מי הוא זה שיעלה את האברים לכבש, אלא אותו כהן שזכה בפייס שהוא יהא \u0003המעלה\u0004 את ה\u0003אברים לכבש הוא\u0004 גם כן זה ש\u0003מעלה אותן\u0004 מן הכבש \u0003על גבי המזבח\u0004 להקריבם. אותם כהנים שלא זכו בפייסות, ועדיין הם לבושים בבגדי כהונה (שהרי כל המשתתפים בפייסות היו לבושים בבגדי כהונה, שאם יזכו — יהיו מוכנים מיד לעבודתם), \u0003מסרום ל\u0004ידי ה\u0003חזנים\u0004 (שמשים, עוזריו של הממונה על בגדי כהונה), והללו \u0003היו מפשיטין אותם\u0004 את הכהנים \u0003את בגדיהם\u0004 (בגדי כהונה), \u0003ולא היו מניחין עליהם אלא מכנסים בלבד,\u0004 ולאחר שחזרו הכהנים ולבשו את בגדיהם של חול, היו פושטים את מכנסי כהונה ולובשים תחתם מכנסי חול. \u0003ו\u0004ארבעה \u0003חלונות\u0004 (כעין תאי אחסון) \u0003היו שם\u0004 במקדש לכל משמר כהונה, ששימשו להנחתם של בגדי הכהונה השונים, \u0003ו\u0004היה \u0003כתוב עליהם\u0004 על כל אחד מהחלונות הללו \u0003תשמיש הכלים\u0004 (הבגדים) השונים (\"מצנפות\", \"אבנטים\", \"כתנות\", \"מכנסים\"). \u0003מי\u0004 מהכהנים \u0003שזכה ב\u0004הקטרת ה\u0003קטרת, היה נוטל את הכף\u0004 המשמשת לנשיאת הקטורת בתוכה, \u0003והכף\u0004 הריהי \u0003דומה לתרקב\u0004 (כלי) \u0003גדול של זהב,\u0004 ה\u0003מחזקת\u0004 (שיש בה בית קיבול בשיעור) \u0003שלשה קבין, והבזך\u0004 (כף קטנה) \u0003היה\u0004 נתון \u0003בתוכו\u0004 של הכף.","",""],["והבזך היה \u0003מלא וגדוש\u0004 ב\u0003קטרת, וכסוי היה לו\u0004 לבזך, על מנת שלא תפול ממנו הקטורת. \u0003וכמין מטוטלת\u0004 (מטלית, חתיכת בגד) \u0003היה עליו\u0004 על הכיסוי \u0003מלמעלן.\u0004","\u0003מי\u0004 מהכהנים \u0003שזכה ב\u0004הבאת ה\u0003מחתה\u0004 עם הגחלים למזבח הפנימי שבהיכל, לצורך ההקטרה, \u0003נטל\u0004 את \u0003מחתת הכסף ועלה לראש המזבח\u0004 החיצון, \u0003ופנה\u0004 שם \u0003את הגחלים\u0004 החיצוניים שכבר כבו \u0003הילך\u0004 והילך (לכאן ולכאן, לצדדים), \u0003ו\u0004לאחר מכן \u0003חתה\u0004 (נטל גחלי אש) \u0003(מן\u0004 הגחלים \u0003המאוכלות הפנימיות\u0004 שעדיין האש לוחשת בתוכן\u0003),\u0004 כדי ארבעה קבים. ואחר \u0003ירד\u0004 מן המזבח \u0003ועירן\u0004 (שפכם) \u0003לתוך\u0004 מחתה \u0003של זהב.\u0004 וכיון שבית קיבולה של מחתת הזהב לא היה אלא כדי שלשה קבים, \u0003נתפזר\u0004 בעירוי זה \u0003ממנו\u0004 ממחתת הכסף \u0003כקב גחלים\u0004 על קרקע העזרה, \u0003והיה מכבדן\u0004 (מטאטא) אותם \u0003לאמה\u0004 של מים העוברת בעזרה, המנקזת את הנשפכים אל מחוץ למקדש.","\u0003ובשבת\u0004 שאסור בה לכבות אש, לא היה עושה כן (שהרי יש בדבר משום כיבוי), אלא \u0003היה כופה עליהן פסכתר\u0004 (כעין סיר גדול). \u0003ו\u0004מסבירים מהו \u0003פסכתר\u0004 זה: \u0003היתה כלי גדול\u0004 ה\u0003מחזקת\u0004 (בעלת קיבול) כמידת \u0003לתך\u0004 (חמש עשרה סאה). \u0003ו\u0004כיון שהיתה הפסכתר כבדה ביותר, \u0003שתי שרשרות היו בה\u0004 לצורך השימוש הרגיל בה שהוא הסרת הדשן מעל גבי המזבח: שרשרת \u0003אחת\u0004 — \u0003שהוא\u0004 כהן אחד \u0003מושך בה\u0004 והדשן בתוכה \u0003ויורד\u0004 מן הכבש. \u0003ו\u0004שרשרת \u0003אחת שהוא\u0004 (כהן נוסף) היה עומד ו\u0003אוחז בה מלמעלן, בשביל שלא תתגלגל\u0004 הפסכתר מהכבש (שהיה משופע) ותשמט מידיו של הכהן המוריד אותה, ויתפזר הדשן.","","\u0003ו\u0004לצורך \u0003שלשה דברים\u0004 במקדש \u0003היתה משמשת\u0004 הפסכתר: בשבת היו \u0003כופין אותה על גבי\u0004 קב ה\u0003גחלים\u0004 שהתפזרו בעירוי ממחתת הכסף למחתת הזהב (כפי ששנינו למעלה), \u0003ו\u0004כן היו כופים אותה \u0003על השרץ\u0004 המת שנמצא במקדש ביום ה\u0003שבת,\u0004 לבל ייטמאו כהנים בשרץ, ואין יכולים להוציא את השרץ מהמקדש בשבת, שמוקצה הוא. \u0003ומורידין בה את הדשן מעל גבי המזבח,\u0004 כדרך שהוסבר למעלה. כאשר \u0003הגיעו\u0004 אותם שני הכהנים, זה שעבודתו בחתיית הגחלים וזה שעבודתו בהקטרת הקטורת, בדרכם להיכל, אל \u0003בין האולם ולמזבח, נטל אחד\u0004 מהם \u0003את\u0004 כלי \u0003המגרפה וזורקה בין האולם ולמזבח\u0004, כדי להשמיע קול, ואותו קול היה כה גדול עד ש\u0003אין אדם שומע\u0004 את \u0003קול חבירו\u0004 המדבר אליו בכל מקום ב\u0003בירושלים מ\u0004חמת \u0003קול המגרפה. ו\u0004לצורך \u0003שלשה דברים היתה משמשת\u0004 המגרפה בהשמעת קול זה: כל \u0003כהן\u0004 שלא נמצא בעזרה, כיון \u0003ש\u0004הוא \u0003שומע את קולה\u0004 של המגרפה — \u0003יודע\u0004 הוא \u0003ש\u0004באותה עת \u0003אחיו הכהנים נכנסים\u0004 עתה \u0003להשתחוות\u0004 בהיכל, \u0003והוא רץ ובא\u0004 ומשתחוה אתם. \u0003ו\u0004כמו כן, כל \u0003בן לוי\u0004 מן המשוררים, כיון \u0003שהוא שומע את קולה\u0004 של המגרפה — \u0003יודע\u0004 הוא \u0003ש\u0004באותה עת \u0003אחיו הלוים נכנסים\u0004 לעזרה, לעמוד על דוכנם, ו\u0003לדבר בשיר\u0004 בשעת הניסוך, \u0003והוא רץ ובא\u0004 ושר אתם. \u0003ו\u0004כן היה משמש קול המגרפה, שבאותה עת היה \u0003ראש המעמד\u0004 (הממונה על העומדים בעזרה מקרב בני ישראל, כשלוחיהם) \u0003היה מעמיד את\u0004 המשוררים \u0003הטמאים בשער המזרח\u0004 של העזרה, שיוכלו אחר כך לטהר אותם בהזייה.","","","\u0003החלו\u0004 אלה שני הכהנים, זה שעבודתו בחתיית הגחלים וזה שעבודתו בהקטרת הקטורת, \u0003עולים ב\u0004שתים עשרה \u0003מעלות האולם, מי\u0004 מהכהנים \u0003שזכו בדישון\u0004 ה\u0003מזבח הפנימי ו\u0004בדישון \u0003המנורה היו מקדימים\u0004 ללכת \u0003לפניהם,\u0004 על מנת שיוציאו את הכלים שנשארו בהיכל. ובאופן זה: \u0003מי שזכה בדישון\u0004 ה\u0003מזבח הפנימי\u0004 — \u0003נכנס\u0004 אל ההיכל \u0003ונטל\u0004 משם \u0003את הטני\u0004 (כלי שבית קיבולו חצי סאה) המונח שם לאחר שדושן המזבח הפנימי (כמבואר למעלה, ל,ב) \u0003ו\u0004כיון שגמר את עבודתו, \u0003השתחוה\u0004 שם בפשיטת ידים ורגלים, \u0003ויצא\u0004 אל מחוץ להיכל. \u0003מי שזכה בדישון המנורה\u0004 — \u0003נכנס\u0004 להיכל, \u0003ומצא שתי נרות (מערביים)\u0004 מזרחיים עדיין \u0003דולקין\u0004 במנורה — הריהו \u0003מדשן\u0004 (מכבה ומנקה אותן משאריותיהן, ומכניס פתילה ושמן חדשים) \u0003את\u0004 הנר \u0003המזרחי\u0004 (הנר החיצוני ביותר שלצד מזרח), \u0003ומניח את\u0004 \u0003הנר השני לצד מזרח, זה\u0004 \u0003המערבי\u0004 לנר המזרחי ביותר, כשהוא \u0003דולק. ש\u0004כן מצוות ההדלקה במנורה היא, בין השאר, ש\u0003ממנו\u0004 (מנר מערבי זה) \u0003היה מדליק את\u0004 כל נרות \u0003המנורה\u0004 בהדלקה \u0003של בין הערבים.\u0004 ואם כשנכנס להיכל \u0003מצאו\u0004 הכהן \u0003ש\u0004נר מערבי זה \u0003כבה\u0004 — הריהו \u0003מדשנו ומדליקו מ\u0004האש שעל \u0003מזבח העולה.\u0004 ולאחר מכן \u0003נטל את הכוז\u0004 (כלי הדומה לקיתון גדול. רמב\"ם) שבו היה נתון דשן המנורה, \u0003מ\u0004מקומו ב\u0003מעלה\u0004 ה\u0003שניה\u0004 שלפני המנורה, \u0003והשתחוה ויצא.\u0004 \u0003מי שזכה ב\u0004הבאת ה\u0003מחתה\u0004 עם הגחלים אל המזבח הפנימי, לצורך הקטרת הקטורת — בתחילה \u0003צבר\u0004 (עשה כעין ערימה) \u0003את הגחלים\u0004 במחתתו \u0003על גבי המזבח\u0004 הפנימי, \u0003ו\u0004לאחר מכן \u0003רדדן\u0004 (שטח אותם) \u0003ב\u0004אמצעות \u0003שולי\u0004 (תחתית) \u0003המחתה\u0004 על גבי המזבח, שפיזר את הגחלים בשווה, \u0003והשתחוה, ויצא.\u0004 \u0003מי שזכה ב\u0004הקטרת ה\u0003קטרת\u0004 — \u0003היה נוטל את הבזך\u0004 המלא וגדוש בקטורת \u0003מתוך הכף\u0004 בו נמצא הבזך, ונותנו לבזך \u0003לאוהבו או לקרובו\u0004 הכהן, אותו הועיד לבוא ולסייעו, ונכנס עמו להיכל לשם כך. \u0003נתפזר ממנו\u0004 מן הבזך \u0003לתוכו\u0004 של הכף — \u0003נותנו לו\u0004 הנלווה אליו את הקטורת \u0003בחפניו\u0004 של הכהן המקטיר. \u0003ומלמדים אותו,\u0004 את הכהן המקטיר (שהרי לא הקטיר עד כה): \u0003הוי זהיר שמא תתחיל\u0004 לפזר את הקטורת \u0003מפניך\u0004 (בצד המזבח הסמוך אליך), אלא התחל לפזר את הקטורת מהצד הרחוק ממך ורק אחר כך פזר אותה בצד הקרוב לך. על מנת \u0003שלא תכוה\u0004 מן הקטורת הבוערת, כאשר תצטרך לפזר את הקטורת על המזבח בצד המרוחק יותר ממך.","","","","\u0003התחיל מרדדן\u0004 (שוטחם) על אש המזבח, \u0003ו\u0004כאשר התמלא הבית עשן מהקטורת, הריהו \u0003יוצא\u0004 מההיכל. וכלל הוא כי \u0003לא היה\u0004 הכהן \u0003המקטיר מקטיר\u0004 את הקטורת \u0003עד שהממונה אומר לו: הקטר! ואם היה\u0004 הכהן המקטיר \u0003כהן גדול, הממונה אומר לו\u0004 בדרך כבוד: \u0003\"אישי כהן גדול, הקטר\"!\u0004","בשעת ההקטרה \u0003פרשו\u0004 (יצאו) \u0003העם\u0004 (כל הכהנים) מבין האולם ולמזבח, ועמד הכהן \u0003והקטיר\u0004 (שכן כלל הוא שבכל כפרה הנעשית בהיכל, אין אדם מורשה להיות בין האולם ולמזבח, כנאמר: \"וכל אדם לא יהיה באהל מועד בבואו לכפר בקודש\". ויקרא טז, יז), \u0003והשתחוה ויצא.\u0004",""],["לאחר שסיימו הכהנים את הקרבת קרבן התמיד של שחר, הריהם נכנסים להיכל להשתחוות, ו\u0003בזמן ש\u0004ה\u0003כהן\u0004 ה\u0003גדול\u0004 נמצא במקדש, הריהו \u0003נכנס\u0004 להיכל תחילה \u0003להשתחות,\u0004 ואחריו משתחוים שאר הכהנים. וכיצד נעשית השתחוואה זו של הכהן הגדול? מפני כבודו של הכהן הגדול היו \u0003שלשה\u0004 כהנים \u0003אוחזין בו\u0004 לסייעו ולתומכו בהליכתו, להבדילו מכל שאר הכהנים שבעזרה הנכנסים אף הם להיכל להשתחוות. כהן \u0003אחד\u0004 אוחז \u0003ב\u0004יד \u0003ימינו,\u0004 \u0003ו\u0004כהן \u0003אחד\u0004 אוחז \u0003ב\u0004יד \u0003שמאלו,\u0004 \u0003ו\u0004כהן \u0003אחד\u0004 אוחז \u0003ב\u0004שתי ה\u0003אבנים\u0004 ה\u0003טובות\u0004 (אבני השוהם) שעל כתפות האיפוד שמאחורי הכהן הגדול.","\u0003וכיון ששמע הממונה\u0004 את \u0003קול\u0004 הפעמונים שבשולי המעיל שעל \u0003רגליו של\u0004 ה\u0003כהן\u0004 ה\u0003גדול,\u0004 ידע \u0003ש\u0004הוא סיים את ההשתחוואה, ועתה \u0003הוא יוצא\u0004 מההיכל, עמד ו\u0003הגביה לו את הפרוכת\u0004 התלויה בפתחו של האולם. ולאחר שהכהן הגדול \u0003נכנס (יוצא) והשתחוה, ויצא, נכנסו\u0004 שאר \u0003אחיו הכהנים,\u0004 ו\u0003השתחוו ויצאו\u0004 אף הם.","ולאחר שהכהנים השתחוו ויצאו מההיכל, \u0003באו ועמדו על\u0004 שתים עשרה ה\u0003מעלות\u0004 שלפני \u0003האולם.\u0004 ואופן עמידתם כך הוא: \u0003עמדו\u0004 חמשת הכהנים \u0003הראשונים\u0004 השנויים בפרק הקודם (מדשן המזבח הפנימי, מדשן המנורה, המחזיק במחתה, מקטיר הקטורת ואוהבו), \u0003לדרום\u0004 (בצד ימינם) של \u0003אחיהם הכהנים\u0004 שעבדו בהעלאת אברי קרבן התמיד למזבח. \u0003וחמשה כלים בידם\u0004 של אלה הראשונים, ואלו הם: \u0003ה\u0004כלי הנקרא \u0003\"טני\"\u0004 (בו דישן הכהן את המזבח הפנימי) — \u0003ביד\u0004 כהן \u0003אחד\u0004 (מדשן המזבח הפנימי). \u0003וה\u0004כלי הנקרא \u0003\"כוז\"\u0004 (בו ניתן הדשן מהטבת הנרות) \u0003ביד\u0004 כהן \u0003אחד\u0004 (מדשן המנורה). \u0003והמחתה\u0004 (בה הוכנסו הגחלים למזבח הפנימי) — \u0003ביד\u0004 כהן \u0003אחד\u0004 (מכניס הגחלים). \u0003והבזך\u0004 (בה ניתנה הקטורת) — \u0003ביד\u0004 כהן \u0003אחד\u0004 המקטיר את הקטורת. \u0003ו\u0004ה\u0003כף\u0004 בה נתון הבזך \u0003וכסויו\u0004 — \u0003ביד\u0004 כהן \u0003אחד\u0004 (אוהבו של המקטיר).","הניחו הכהנים בתחילה את כליהם, ועמדו \u0003וברכו את העם ברכה אחת,\u0004 ברכת כהנים. וברכת כהנים שבמקדש הריהי כברכת כהנים שמחוץ למקדש (\"מדינה\"), ואין היא נבדלת ממנה \u0003אלא שבמדינה אומרים אותה\u0004 הכהנים כ\u0003שלש ברכות,\u0004 שמפסיקים בין פסוק לפסוק, והשומעים עונים \"אמן\" על כל ברכה וברכה, \u0003ו\u0004אילו \u0003במקדש\u0004 שלשת פסוקי ברכת כהנים נאמרים כ\u0003ברכה אחת,\u0004 ואין השומעים עונים \"אמן\" בין פסוק לפסוק, אלא בסוף אומרים \"ברוך ה' אלקי ישראל מן העולם ועד העולם\". ועוד: שבברכת כהנים הנאמרת \u0003במקדש היו\u0004 הכהנים \u0003אומרים את השם\u0004 המפורש \u0003ככתבו\u0004 (כדרך שהוא כתוב: יו\"ד, ה\"א, וא\"ו, ה\"א), \u0003ו\u0004אילו \u0003במדינה\u0004 — אומרים הכהנים את השם \u0003בכנויו\u0004 (בלשון אדנות).","ועוד: שבברכת כהנים הנאמרת \u0003במדינה\u0004 — \u0003הכהנים נושאים את ידיהם כנגד כתפיהם,\u0004 ולא גבוה יותר. \u0003ו\u0004אילו \u0003במקדש\u0004 — הכהנים נושאים את כפיהם מ\u0003על גבי ראשיהן.\u0004 אין דברים אלה אמורים אלא בשאר הכהנים שבמקדש, \u0003חוץ מכהן גדול, שאין\u0004 הוא נושא את כפיו למעלה מראשו, שאסור שיהא \u0003מגביה את ידיו למעלה מן הציץ\u0004 הנתון על מצחו, לפי שעל הציץ כתוב שם ה'. \u0003ר' יהודה אומר: אף כהן גדול\u0004 המברך ברכת כהנים נושא כפיו מעל לראשו, ו\u0003מגביה את ידיו למעלה מן הציץ, ש\u0004כן \u0003נאמר\u0004 בברכת כהנים שברך אהרן שהיה כהן גדול \u0003\"וישא אהרן את ידיו אל העם ויברכם\"\u0004 (ויקרא ט, כב).","","","","","","","ג משנה כלל הוא שרשאי הכהן הגדול להקריב בכל עת שירצה כל קרבן הקרב במקדש, ולכן, \u0003בזמן שכהן גדול רוצה להקטיר\u0004 (להקריב את אברי קרבן התמיד ומנחתו) \u0003היה עולה בכבש\u0004 אל המזבח, \u0003והסגן\u0004 (הכהן הממונה תחתיו) מהלך עמו \u0003ב\u0004צד \u0003ימינו.\u0004 ואם אירע ו\u0003הגיע\u0004 הכהן הגדול \u0003למחצית הכבש,\u0004 והתעייף — \u0003אחז הסגן בימינו, והעלהו\u0004 לראש הכבש, אל המזבח. \u0003והושיט לו\u0004 הכהן \u0003הראשון\u0004 מתשעת הכהנים שזכו בפייס בהעלאת אברים למזבח, את \u0003הראש והרגל\u0004 של הקרבן — \u0003וסמך\u0004 הכהן הגדול \u0003עליהן\u0004 את ידיו, \u0003ו\u0004לאחר מכן \u0003זרקן\u0004 על אש המזבח. ולאחר מכן \u0003הושיט\u0004 הכהן \u0003השני ל\u0004כהן ה\u0003ראשון\u0004 את \u0003שתי הידים\u0004 (הרגלים הקדמיות) של הקרבן, והוא \u0003נותנן לכהן גדול\u0004 — וחזר הכהן הגדול \u0003וסמך עליהן, וזרקן\u0004 על אש המזבח. ולאחר מכן \u0003נשמט\u0004 (עזב) הכהן \u0003השני והלך לו,\u0004 שהרי אין בו עוד צורך לעבודה. ואילו הכהן הראשון נשאר על מקומו, שהרי הוא המגיש לכהן הגדול את שאר האברים הקרבים. \u0003וכך היו\u0004 שאר הכהנים שזכו בהעלאת האברים \u0003מושיטין לו\u0004 לכהן הראשון, בזה אחר זה, כסדר העלאת האברים, את \u0003שאר כל האברין\u0004 הקרבים, והכהן הראשון מושיטן לכהן הגדול המקריב, \u0003והוא\u0004 הכהן הגדול \u0003סומך עליהן וזורקן. ובזמן שהוא\u0004 הכהן הגדול \u0003רוצה\u0004 — \u0003הוא סומך\u0004 רק על אברי הקרבן, \u0003ו\u0004כהנים \u0003אחרים\u0004 הם ה\u0003זורקין\u0004 את האברים על אש המזבח. ובשעה ש\u0003בא לו\u0004 (הגיע העת) שהכהן הגדול נדרש \u0003להקיף את המזבח,\u0004 על מנת להגיע לפינה המערבית דרומית של המזבח, מקום בו נעשה ניסוך היין, \u0003מהיכן הוא מתחיל\u0004 (שהרי הוא עומד בראש הכבש, הנמצא בצד דרומו של המזבח)? — הריהו פונה לצד ימין \u0003מקרן דרומית מזרחית,\u0004 וממשיך והולך לקרן \u0003מזרחית צפונית,\u0004 ולאחר מכן לקרן \u0003צפונית מערבית,\u0004 ולבסוף מגיע לקרן \u0003מערבית דרומית.\u0004 וכשמגיע למקום זה של ניסוך היין, \u0003נתנו לו\u0004 הכהנים העומדים שם \u0003יין לנסך.\u0004 \u0003הסגן עומד\u0004 בצידו של הכהן הגדול, \u0003על\u0004 (בסמוך) \u0003הקרן, והסודרים בידו,\u0004 מוכנים להנפתם כאשר ינסך הכהן הגדול את היין, וידעו הלויים לפתוח באותה שעה בשיר, ו\u0003שני כהנים עומדין על שלחן החלבים\u0004 (שולחן השיש, עליו נתונים איברי הקרבנות לפני העלאתם למזבח), \u0003ושתי חצוצרות\u0004 של כסף היו \u0003בידם,\u0004 מוכנים להריע בהן כשינסך הכהן את היין. שבחצוצרות אלה \u0003תקעו\u0004 בקול תקיעה הפשוט וממושך, והריעו בקול תרועה המקוטע, וחזרו \u0003ותקעו.\u0004 \u0003באו ועמדו אצל בן ארזא,\u0004 הממונה על כלי הזמר הנקרא צלצל, \u0003אחד מימינו\u0004 של בן ארזה \u0003ואחד משמאלו.\u0004 ובשעה ש\u0003שחה\u0004 (התכופף) הכהן \u0003לנסך\u0004 את היין, \u0003והניף הסגן בסודרים,\u0004 שיראו הלויים המשוררים, \u0003והקיש בן ארזא בצלצל,\u0004 והכהנים תקעו והריעו ותקעו בחצוצרות, \u0003ודברו הלוים בשיר\u0004 של אותו יום מימות השבוע. והיה השיר מחולק לשלשה פרקים. ובכל עת ש\u0003הגיעו\u0004 הלויים \u0003לפרק\u0004 מפרקי השיר, הכהנים \u0003תקעו, והשתחוו העם\u0004 הנמצאים בעזרה. שכן \u0003על כל פרק\u0004 ופרק מפרקי השיר — \u0003תקיעה, ועל כל תקיעה\u0004 — \u0003השתחויה. זהו סדר התמיד לעבודת בית אלהינו, יהי רצון שיבנה במהרה בימינו, אמן.\u0004 \u0003השיר שהיו הלוים אומרים במקדש: ביום הראשון היו אומרים\u0004 את המזמור (הנפתח במלים \"לדוד מזמור\") \u0003\"לה' הארץ ומלואה תבל ויושבי בה\"\u0004 (תהלים כד). \u0003ב\u0004יום ה\u0003שני היו אומרים\u0004 את המזמור (הנפתח במלים \"שיר מזמור לבני קרח\") \u0003\"גדול ה' ומהולל מאד בעיר אלהינו הר קדשו\"\u0004 (שם מח). \u0003ב\u0004יום ה\u0003שלישי היו אומרים\u0004 את המזמור (הנפתח במלים \"מזמור לאסף\") \u0003\"אלהים נצב בעדת אל בקרב אלהים ישפוט\"\u0004 (שם פב). \u0003ב\u0004יום ה\u0003רביעי היו אומרים\u0004 את המזמור \u0003\"אל נקמות ה' אל נקמות הופיע\"\u0004 (שם צד). \u0003ב\u0004יום ה\u0003חמישי היו אומרים\u0004 את המזמור (הנפתח במלים \"למנצח על הגתית לאסף\") \u0003\"הרנינו לאלהים עוזנו הריעו לאלהי יעקב\"\u0004 (שם פא). \u0003ב\u0004יום ה\u0003ששי היו אומרים\u0004 את המזמור \u0003\"ה' מלך גאות לבש לבש\" וגומר\u0004 (שם צג). \u0003ב\u0004יום ה\u0003שבת היו אומרים\u0004 את המזמור \u0003\"מזמור שיר ליום השבת\"\u0004 (שם צב) — \u0003מזמור שיר לעתיד לבוא, ליום שכולו שבת ומנוחה לחיי העולמים.\u0004"]]};
